def _format_quality_rate(value: object) -> str:
    if not isinstance(value, (int, float)):
        return "n/a"
    return f"{float(value) * 100:.1f}%"


def _format_quality_age(seconds: object) -> str:
    if not isinstance(seconds, (int, float)):
        return "unknown"
    total = max(0, int(seconds))
    if total < 60:
        return f"{total}s ago"
    minutes = total // 60
    if minutes < 60:
        return f"{minutes}m ago"
    hours = minutes // 60
    if hours < 48:
        return f"{hours}h ago"
    return f"{hours // 24}d ago"


async def _interaction_quality_db_snapshot(db: AsyncSession) -> dict:
    since = datetime.now(timezone.utc) - timedelta(days=7)

    async def _count(model, *criteria) -> int:
        result = await db.execute(select(func.count()).select_from(model).where(*criteria))
        return int(result.scalar() or 0)

    visits = await _count(
        PublicVisitEvent,
        PublicVisitEvent.created_at >= since,
        PublicVisitEvent.is_internal.is_(False),
        PublicVisitEvent.is_bot.is_(False),
    )
    unique_visitors_result = await db.execute(
        select(func.count(func.distinct(PublicVisitEvent.visitor_hash))).where(
            PublicVisitEvent.created_at >= since,
            PublicVisitEvent.is_internal.is_(False),
            PublicVisitEvent.is_bot.is_(False),
        )
    )
    unique_visitors = int(unique_visitors_result.scalar() or 0)
    project_count = await _count(ProjectPortalProject, ProjectPortalProject.created_at >= since)
    account_count = await _count(ProjectPortalAccount, ProjectPortalAccount.created_at >= since)
    discovery_count = await _count(
        ProjectPortalDiscoverySession,
        ProjectPortalDiscoverySession.created_at >= since,
    )
    blueprint_count = await _count(ProjectPortalBlueprint, ProjectPortalBlueprint.created_at >= since)
    path_rows = (
        await db.execute(
            select(PublicVisitEvent.path, func.count())
            .where(
                PublicVisitEvent.created_at >= since,
                PublicVisitEvent.is_internal.is_(False),
                PublicVisitEvent.is_bot.is_(False),
            )
            .group_by(PublicVisitEvent.path)
            .order_by(func.count().desc())
            .limit(8)
        )
    ).all()
    recent_projects = (
        await db.execute(
            select(ProjectPortalProject)
            .order_by(ProjectPortalProject.created_at.desc())
            .limit(8)
        )
    ).scalars().all()
    return {
        "window_days": 7,
        "visits": visits,
        "unique_visitors": unique_visitors,
        "registered_accounts": account_count,
        "visitor_projects": project_count,
        "discovery_sessions": discovery_count,
        "blueprints": blueprint_count,
        "top_paths": [{"path": str(path or "/"), "count": int(count or 0)} for path, count in path_rows],
        "recent_projects": [
            {
                "id": int(project.id),
                "title": project.title,
                "status": project.status,
                "mode": project.mode,
                "created_at": project.created_at.isoformat() if project.created_at else "",
            }
            for project in recent_projects
        ],
    }


def _interaction_quality_html(snapshot: dict) -> str:
    quality = snapshot.get("quality") if isinstance(snapshot.get("quality"), dict) else {}
    activity = snapshot.get("activity") if isinstance(snapshot.get("activity"), dict) else {}
    headline = quality.get("headline") if isinstance(quality.get("headline"), dict) else {}
    artifacts = quality.get("artifacts") if isinstance(quality.get("artifacts"), list) else []
    failure_analysis = quality.get("failure_analysis") if isinstance(quality.get("failure_analysis"), dict) else {}
    actions = quality.get("next_actions") if isinstance(quality.get("next_actions"), list) else []

    def esc(value: object) -> str:
        return html.escape(str(value if value is not None else ""))

    def artifact_rows() -> str:
        rows = []
        for item in artifacts:
            rows.append(
                "<tr>"
                f"<td>{esc(item.get('key'))}</td>"
                f"<td>{'yes' if item.get('available') else 'no'}</td>"
                f"<td>{_format_quality_rate(item.get('weighted_pass_rate'))}</td>"
                f"<td>{esc(item.get('scenario_count') or 0)}</td>"
                f"<td>{esc(item.get('internal_jargon_failure_count') or 0)}</td>"
                f"<td>{esc(_format_quality_age(item.get('age_seconds')))}</td>"
                "</tr>"
            )
        return "\n".join(rows) or "<tr><td colspan='6'>No artifacts found.</td></tr>"

    def surface_rows() -> str:
        rows = []
        for artifact in artifacts:
            for surface in artifact.get("surfaces") or []:
                tone = "ok" if surface.get("available") and not surface.get("failure_count") else "warn"
                rows.append(
                    f"<tr data-tone='{tone}'>"
                    f"<td>{esc(artifact.get('key'))}</td>"
                    f"<td>{esc(surface.get('surface'))}</td>"
                    f"<td>{'yes' if surface.get('available') else 'no'}</td>"
                    f"<td>{_format_quality_rate(surface.get('weighted_pass_rate'))}</td>"
                    f"<td>{esc(surface.get('passed_count') or 0)}/{esc(surface.get('scenario_count') or 0)}</td>"
                    f"<td>{esc(surface.get('unavailable_reason') or '')}</td>"
                    "</tr>"
                )
        return "\n".join(rows) or "<tr><td colspan='6'>No surface data yet.</td></tr>"

    def count_rows(key: str, label: str) -> str:
        rows = []
        for item in failure_analysis.get(key) or []:
            rows.append(f"<tr><td>{esc(item.get(label))}</td><td>{esc(item.get('count'))}</td></tr>")
        return "\n".join(rows) or "<tr><td colspan='2'>None</td></tr>"

    def example_rows() -> str:
        rows = []
        for item in failure_analysis.get("examples") or []:
            rows.append(
                "<tr>"
                f"<td>{esc(item.get('surface'))}</td>"
                f"<td>{esc(item.get('bucket'))}</td>"
                f"<td>{esc(', '.join(item.get('failures') or []))}</td>"
                f"<td>{esc(item.get('turn'))}</td>"
                f"<td>{esc(item.get('reply_excerpt'))}</td>"
                "</tr>"
            )
        return "\n".join(rows) or "<tr><td colspan='5'>No failing examples in loaded reports.</td></tr>"

    def action_cards() -> str:
        cards = []
        for item in actions:
            cards.append(
                "<article class='action'>"
                f"<strong>{esc(item.get('priority'))}: {esc(item.get('action'))}</strong>"
                f"<span>Owner: {esc(item.get('owner'))}</span>"
                f"<small>Evidence: {esc(item.get('evidence'))}</small>"
                "</article>"
            )
        return "\n".join(cards)

    def top_path_rows() -> str:
        return "\n".join(
            f"<tr><td>{esc(item.get('path'))}</td><td>{esc(item.get('count'))}</td></tr>"
            for item in activity.get("top_paths") or []
        ) or "<tr><td colspan='2'>No visit paths recorded.</td></tr>"

    def project_rows() -> str:
        return "\n".join(
            f"<tr><td>{esc(item.get('title'))}</td><td>{esc(item.get('status'))}</td><td>{esc(item.get('mode'))}</td><td>{esc(item.get('created_at'))}</td></tr>"
            for item in activity.get("recent_projects") or []
        ) or "<tr><td colspan='4'>No visitor projects recorded.</td></tr>"

    generated = esc(snapshot.get("generated_at") or quality.get("generated_at") or "")
    return f"""<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>MIM Interaction Quality</title>
  <style>
    :root {{ color-scheme: light; --ink:#172033; --muted:#667085; --line:#d8e0ec; --panel:#ffffff; --bg:#f5f7fb; --accent:#1267d6; --ok:#0f8a56; --warn:#b54708; }}
    * {{ box-sizing: border-box; }}
    body {{ margin:0; font-family: Inter, Segoe UI, Arial, sans-serif; background:var(--bg); color:var(--ink); }}
    header {{ padding:24px 28px 12px; background:#0f2545; color:white; }}
    header h1 {{ margin:0 0 6px; font-size:28px; letter-spacing:0; }}
    header p {{ margin:0; color:#c7d7ef; }}
    main {{ padding:22px 28px 40px; max-width:1480px; margin:0 auto; }}
    .grid {{ display:grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap:14px; margin-bottom:18px; }}
    .card, section {{ background:var(--panel); border:1px solid var(--line); border-radius:8px; padding:16px; box-shadow:0 8px 18px rgba(16, 24, 40, .06); }}
    .card small, .muted {{ color:var(--muted); display:block; margin-top:4px; }}
    .metric {{ font-size:30px; font-weight:750; margin-top:8px; }}
    .metric.ok {{ color:var(--ok); }} .metric.warn {{ color:var(--warn); }}
    .sections {{ display:grid; grid-template-columns: minmax(0, 1.1fr) minmax(360px, .7fr); gap:18px; align-items:start; }}
    section {{ margin-bottom:18px; }}
    h2 {{ margin:0 0 12px; font-size:18px; }}
    table {{ width:100%; border-collapse:collapse; font-size:13px; }}
    th, td {{ padding:9px 8px; border-bottom:1px solid #edf1f7; text-align:left; vertical-align:top; }}
    th {{ color:#40516d; font-size:12px; text-transform:uppercase; letter-spacing:.04em; }}
    tr[data-tone="warn"] td {{ background:#fff8ed; }}
    .actions {{ display:grid; gap:10px; }}
    .action {{ border:1px solid var(--line); border-radius:8px; padding:12px; background:#fbfcff; }}
    .action span, .action small {{ display:block; color:var(--muted); margin-top:5px; }}
    .wide {{ grid-column:1 / -1; }}
    @media (max-width: 980px) {{ .grid, .sections {{ grid-template-columns:1fr; }} main {{ padding:16px; }} }}
  </style>
</head>
<body>
  <header>
    <h1>MIM Interaction Quality</h1>
    <p>Smoke results, customer-facing failure modes, visitor activity, and next actions. Generated {generated}.</p>
  </header>
  <main>
    <div class="grid">
      <div class="card"><strong>Best Weighted Pass</strong><div class="metric ok">{_format_quality_rate(headline.get('best_weighted_pass_rate'))}</div><small>Target is 95%+ across surfaces.</small></div>
      <div class="card"><strong>Artifacts Loaded</strong><div class="metric">{esc(headline.get('available_artifacts') or 0)}</div><small>Universal, customer, and general smokes.</small></div>
      <div class="card"><strong>Jargon Leaks</strong><div class="metric {'warn' if int(headline.get('internal_jargon_failure_count') or 0) else 'ok'}">{esc(headline.get('internal_jargon_failure_count') or 0)}</div><small>Must stay at zero.</small></div>
      <div class="card"><strong>7-Day Visitors</strong><div class="metric">{esc(activity.get('unique_visitors') or 0)}</div><small>{esc(activity.get('visits') or 0)} tracked visits, bots/internal excluded.</small></div>
    </div>
    <div class="sections">
      <div>
        <section><h2>Smoke Artifacts</h2><table><thead><tr><th>Artifact</th><th>Loaded</th><th>Weighted</th><th>Scenarios</th><th>Jargon</th><th>Age</th></tr></thead><tbody>{artifact_rows()}</tbody></table></section>
        <section><h2>Surface Certification</h2><table><thead><tr><th>Artifact</th><th>Surface</th><th>Available</th><th>Weighted</th><th>Passed</th><th>Reason</th></tr></thead><tbody>{surface_rows()}</tbody></table></section>
        <section><h2>Failure Examples</h2><table><thead><tr><th>Surface</th><th>Category</th><th>Failures</th><th>User Turn</th><th>Reply Excerpt</th></tr></thead><tbody>{example_rows()}</tbody></table></section>
      </div>
      <div>
        <section><h2>Recommended Next Actions</h2><div class="actions">{action_cards()}</div></section>
        <section><h2>Failure Families</h2><table><thead><tr><th>Family</th><th>Count</th></tr></thead><tbody>{count_rows('family_counts', 'family')}</tbody></table></section>
        <section><h2>Category Failures</h2><table><thead><tr><th>Category</th><th>Count</th></tr></thead><tbody>{count_rows('category_failure_counts', 'category')}</tbody></table></section>
        <section><h2>Visitor Activity</h2><table><thead><tr><th>Path</th><th>Visits</th></tr></thead><tbody>{top_path_rows()}</tbody></table></section>
        <section><h2>Recent Visitor Projects</h2><table><thead><tr><th>Project</th><th>Status</th><th>Mode</th><th>Created</th></tr></thead><tbody>{project_rows()}</tbody></table></section>
      </div>
    </div>
  </main>
</body>
</html>"""


@router.get("/mim/interaction-quality/data")
async def mim_interaction_quality_data(
    request: Request, db: AsyncSession = Depends(get_db)
) -> dict:
    ensure_authenticated_mimtod_api_request(request)
    quality = build_interaction_quality_snapshot()
    activity = await _interaction_quality_db_snapshot(db)
    return {
        "schema_version": "mim-interaction-quality-dashboard-response-v1",
        "generated_at": datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
        "quality": quality,
        "activity": activity,
    }


@router.get("/mim/interaction-quality")
async def mim_interaction_quality_page(
    request: Request, db: AsyncSession = Depends(get_db)
) -> Response:
    snapshot = await mim_interaction_quality_data(request, db)
    return Response(content=_interaction_quality_html(snapshot), media_type="text/html")


def _coerce_web_research_concurrency(
    value: object,
    *,
    fallback: int,
    minimum: int = 1,
    maximum: int = 32,
) -> int:
    try:
        parsed = int(value)
    except Exception:
        parsed = int(fallback)
    return max(minimum, min(maximum, parsed))


def _mic_debug_enabled(payload: dict) -> bool:
    if str(os.getenv("MIM_MIC_DEBUG", "")).strip().lower() in {
        "1",
        "true",
        "yes",
        "on",
    }:
        return True
    return bool(payload.get("debug"))


def _append_mic_debug_event(event: dict) -> None:
    try:
        MIC_TRANSCRIBE_DEBUG_LOG.parent.mkdir(parents=True, exist_ok=True)
        with MIC_TRANSCRIBE_DEBUG_LOG.open("a", encoding="utf-8") as handle:
            handle.write(
                json.dumps(event, ensure_ascii=False, separators=(",", ":")) + "\n"
            )
    except Exception as exc:
        logger.debug("mic_debug_event_write_failed: %s", exc)


def _mic_debug_detail(message: str, trace_id: str) -> dict:
    return {
        "message": message,
        "trace_id": trace_id,
        "debug_log_path": str(MIC_TRANSCRIBE_DEBUG_LOG),
    }


def _classify_provider_error(detail: str) -> dict:
    lowered = detail.lower()
    forbidden_hint = (
        "forbidden" in lowered or " 403" in lowered or "status 403" in lowered
    )
    unauthorized_hint = (
        "unauthorized" in lowered or " 401" in lowered or "status 401" in lowered
    )
    quota_hint = "quota" in lowered or "rate" in lowered or "429" in lowered
    blocked_hint = "blocked" in lowered or "denied" in lowered
    return {
        "forbidden_hint": forbidden_hint,
        "unauthorized_hint": unauthorized_hint,
        "quota_or_rate_hint": quota_hint,
        "blocked_hint": blocked_hint,
        "upstream_status_hint": 403
        if forbidden_hint
        else (401 if unauthorized_hint else (429 if quota_hint else None)),
    }


def _resolve_mic_provider_mode(payload: dict) -> str:
    raw = (
        str(payload.get("provider") or os.getenv("MIM_MIC_PROVIDER") or "")
        .strip()
        .lower()
    )
    if raw in {"local", "pocketsphinx", "offline"}:
        return "local"
    if raw in {"openai", "whisper", "gpt4o", "gpt-4o-mini-transcribe"}:
        return "openai"
    if raw in {"google", "google_web_speech", "cloud"}:
        return "google"
    if raw == "auto":
        return "auto"
    return "auto" if settings.allow_web_access else "local"


def _estimate_wav_audio_metrics(audio_bytes: bytes) -> dict:
    metrics = {
        "audio_duration_ms": 0,
        "sample_rate_hz": 0,
        "channels": 0,
        "sample_width_bytes": 0,
        "rms_dbfs": None,
        "peak_dbfs": None,
        "speech_detected": False,
        "upload_bytes": len(audio_bytes),
    }
    if not audio_bytes:
        return metrics

    try:
        with wave.open(io.BytesIO(audio_bytes), "rb") as wav_file:
            channels = int(wav_file.getnchannels() or 0)
            sample_rate = int(wav_file.getframerate() or 0)
            sample_width = int(wav_file.getsampwidth() or 0)
            frame_count = int(wav_file.getnframes() or 0)
            raw_pcm = wav_file.readframes(frame_count)
    except Exception:
        return metrics

    metrics["sample_rate_hz"] = sample_rate
    metrics["channels"] = channels
    metrics["sample_width_bytes"] = sample_width
    if sample_rate > 0 and frame_count > 0:
        metrics["audio_duration_ms"] = int((frame_count / float(sample_rate)) * 1000)

    if not raw_pcm or sample_width <= 0:
        return metrics

    # Decode PCM samples as signed values and estimate loudness/peak.
    samples: list[int] = []
    max_int = 32767.0
    try:
        if sample_width == 1:
            samples = [int(v) - 128 for v in raw_pcm]
            max_int = 127.0
        elif sample_width == 2:
            arr = array.array("h")
            arr.frombytes(raw_pcm)
            samples = [int(v) for v in arr]
            max_int = 32767.0
        elif sample_width == 4:
            arr = array.array("i")
            arr.frombytes(raw_pcm)
            samples = [int(v) for v in arr]
            max_int = 2147483647.0
        elif sample_width == 3:
            step = 3
            for i in range(0, len(raw_pcm) - 2, step):
                b0 = raw_pcm[i]
                b1 = raw_pcm[i + 1]
                b2 = raw_pcm[i + 2]
                value = b0 | (b1 << 8) | (b2 << 16)
                if value & 0x800000:
                    value -= 0x1000000
                samples.append(int(value))
            max_int = 8388607.0
    except Exception:
        return metrics

    if not samples:
        return metrics

    peak = max(abs(v) for v in samples)
    rms = math.sqrt(sum(float(v) * float(v) for v in samples) / float(len(samples)))
    if peak > 0 and max_int > 0:
        peak_norm = min(1.0, peak / max_int)
        metrics["peak_dbfs"] = round(20.0 * math.log10(max(peak_norm, 1e-12)), 2)
    if rms > 0 and max_int > 0:
        rms_norm = min(1.0, rms / max_int)
        metrics["rms_dbfs"] = round(20.0 * math.log10(max(rms_norm, 1e-12)), 2)

    rms_dbfs = metrics.get("rms_dbfs")
    peak_dbfs = metrics.get("peak_dbfs")
    metrics["speech_detected"] = bool(
        (isinstance(rms_dbfs, (int, float)) and rms_dbfs > -42.0)
        or (isinstance(peak_dbfs, (int, float)) and peak_dbfs > -22.0)
    )
    return metrics


def _local_stt_min_confidence() -> float:
    raw = str(os.getenv("MIM_LOCAL_STT_MIN_CONFIDENCE") or "0.55").strip()
    try:
        value = float(raw)
    except ValueError:
        value = 0.55
    return max(0.0, min(1.0, value))


def _openai_auto_stt_enabled() -> bool:
    raw = str(os.getenv("MIM_MIC_OPENAI_AUTO") or "1").strip().lower()
    return raw in {"1", "true", "yes", "on"}


def _is_low_quality_local_transcript(text: str) -> bool:
    normalized = re.sub(r"[^a-z\s]", " ", str(text or "").lower())
    tokens = [token for token in normalized.split() if token]
    if not tokens:
        return True

    compact = "".join(tokens)
    if len(compact) < 5:
        return True

    if len(tokens) >= 2 and all(len(token) <= 2 for token in tokens):
        return True

    unique_ratio = len(set(tokens)) / float(len(tokens))
    if len(tokens) >= 4 and unique_ratio < 0.5:
        return True

    filler_words = {"um", "uh", "erm", "hmm", "mm", "ah", "eh"}
    if all(token in filler_words for token in tokens):
        return True

    return False


def _normalize_prompt_key(text: str) -> str:
    return " ".join(str(text or "").strip().lower().split())


def _is_clarification_driven(escalation_reasons: list[str], outcome: str) -> bool:
    reasons = {
        str(item).strip().lower()
        for item in (escalation_reasons or [])
        if str(item).strip()
    }
    clarification_reasons = {
        "requires_clarification",
        "ambiguous_command",
        "missing_target",
        "low_transcript_confidence",
    }
    if "unsafe_action_request" in reasons:
        return False
    return outcome in {"store_only", "requires_confirmation", "blocked"} and bool(
        reasons.intersection(clarification_reasons)
    )


def _build_one_clarifier_prompt(transcript: str) -> str:
    request = _normalize_prompt_key(transcript)[:72]
    if request and not _is_low_signal_turn(request):
        return f"For '{request}', I'm missing one detail: do you want me to answer a question, suggest a plan, or take an action?"
    return "I'm missing one detail: do you want me to answer a question, suggest a plan, or take an action?"


def _build_clarification_limit_prompt(
    escalation_reasons: list[str], transcript: str
) -> str:
    reasons = {
        str(item).strip().lower()
        for item in (escalation_reasons or [])
        if str(item).strip()
    }
    if "missing_target" in reasons:
        missing = "the exact object or location"
    elif "low_transcript_confidence" in reasons:
        missing = "a clearer request"
    else:
        missing = "the intended outcome"
    request = _normalize_prompt_key(transcript)[:72]
    if request and not _is_low_signal_turn(request):
        return f"For '{request}', I am still missing {missing}. Options: 1) ask a question, 2) suggest a short plan, 3) request an action."
    return f"I am still missing {missing}. Options: 1) ask a question, 2) suggest a short plan, 3) request an action."


async def _recent_voice_clarification_count(
    db: AsyncSession, *, within_seconds: int = 180
) -> int:
    threshold = datetime.now(timezone.utc) - timedelta(
        seconds=max(30, int(within_seconds))
    )
    rows = (
        (
            await db.execute(
                select(InputEventResolution)
                .where(InputEventResolution.created_at >= threshold)
                .where(InputEventResolution.clarification_prompt != "")
                .order_by(InputEventResolution.id.desc())
                .limit(12)
            )
        )
        .scalars()
        .all()
    )

    count = 0
    for row in rows:
        meta = row.metadata_json if isinstance(row.metadata_json, dict) else {}
        if str(meta.get("source", "")).strip().lower() != "voice":
            continue
        if not _is_clarification_driven(
            row.escalation_reasons or [], str(row.outcome or "")
        ):
            continue
        count += 1
    return count


def _token_overlap_ratio(left: str, right: str) -> float:
    left_tokens = {token for token in _normalize_prompt_key(left).split() if token}
    right_tokens = {token for token in _normalize_prompt_key(right).split() if token}
    if not left_tokens or not right_tokens:
        return 0.0
    overlap = len(left_tokens.intersection(right_tokens))
    return overlap / float(min(len(left_tokens), len(right_tokens)))


async def _has_recent_similar_voice_clarification(
    db: AsyncSession,
    *,
    transcript: str,
    within_seconds: int = 180,
    min_overlap_ratio: float = 0.30,
) -> bool:
    threshold = datetime.now(timezone.utc) - timedelta(
        seconds=max(30, int(within_seconds))
    )
    rows = (
        await db.execute(
            select(InputEventResolution, InputEvent)
            .join(InputEvent, InputEvent.id == InputEventResolution.input_event_id)
            .where(InputEventResolution.created_at >= threshold)
            .where(InputEvent.source == "voice")
            .where(InputEventResolution.clarification_prompt != "")
            .order_by(InputEventResolution.id.desc())
            .limit(8)
        )
    ).all()

    candidate = str(transcript or "").strip()
    for resolution, event in rows:
        reasons = (
            resolution.escalation_reasons
            if isinstance(resolution.escalation_reasons, list)
            else []
        )
        if not _is_clarification_driven(reasons, str(resolution.outcome or "")):
            continue
        prior_text = str(event.raw_input or "").strip()
        if _token_overlap_ratio(candidate, prior_text) >= max(
            0.0, min(1.0, float(min_overlap_ratio))
        ):
            return True
    return False


async def _has_recent_similar_text_precision_prompt(
    db: AsyncSession,
    *,
    transcript: str,
    exclude_event_id: int | None = None,
    session_id: str = "",
    within_seconds: int = 180,
    min_overlap_ratio: float = 0.30,
) -> bool:
    rows = (
        (
            await db.execute(
                select(InputEvent)
                .where(InputEvent.source == "text")
                .order_by(InputEvent.id.desc())
                .limit(max(8, min(24, int(within_seconds // 10) or 8)))
            )
        )
        .scalars()
        .all()
    )

    candidate = str(transcript or "").strip()
    normalized_session = str(session_id or "").strip()
    for event in rows:
        if exclude_event_id is not None and int(event.id) == int(exclude_event_id):
            continue
        if normalized_session:
            event_meta = (
                event.metadata_json if isinstance(event.metadata_json, dict) else {}
            )
            event_session = str(event_meta.get("conversation_session_id", "")).strip()
            if event_session != normalized_session:
                continue
        prior_text = str(event.raw_input or "").strip()
        if _token_overlap_ratio(candidate, prior_text) >= max(
            0.0, min(1.0, float(min_overlap_ratio))
        ):
            return True
    return False


def _lang_to_iso639_1(language: str) -> str:
    normalized = str(language or "en-US").strip().replace("_", "-").lower()
    if not normalized:
        return "en"
    if "-" in normalized:
        return normalized.split("-", 1)[0]
    return normalized[:2]


def _select_tts_voice(language: str, requested_voice: str) -> str:
    requested = str(requested_voice or "").strip()
    if requested:
        return requested

    lang = str(language or "en-US").strip().lower()
    if lang.startswith("en"):
        return "en-US-EmmaMultilingualNeural"
    if lang.startswith("es"):
        return "es-ES-ElviraNeural"
    if lang.startswith("fr"):
        return "fr-FR-DeniseNeural"
    if lang.startswith("de"):
        return "de-DE-SeraphinaMultilingualNeural"
    if lang.startswith("it"):
        return "it-IT-ElsaNeural"
    if lang.startswith("pt"):
        return "pt-BR-FranciscaNeural"
    return "en-US-EmmaMultilingualNeural"


def _is_safe_web_url(raw_url: str) -> bool:
    try:
        parsed = urlparse(str(raw_url or "").strip())
    except Exception:
        return False
    if parsed.scheme not in {"http", "https"}:
        return False
    hostname = str(parsed.hostname or "").strip().lower()
    if not hostname:
        return False
    blocked_hosts = {
        "localhost",
        "127.0.0.1",
        "0.0.0.0",
        "::1",
    }
    if hostname in blocked_hosts:
        return False
    if hostname.endswith(".local"):
        return False
    return True


def _extract_visible_text_from_html(
    raw_html: str, *, max_chars: int = 12000
) -> tuple[str, str]:
    raw_doc = str(raw_html or "")
    title_match = re.search(
        r"<title[^>]*>(.*?)</title>", raw_doc, flags=re.IGNORECASE | re.DOTALL
    )
    title = re.sub(r"\s+", " ", title_match.group(1)).strip() if title_match else ""
    title = html.unescape(title)
    title = re.sub(r"<[^>]+>", " ", title)
    title = re.sub(r"\s+", " ", title).strip()

    without_scripts = re.sub(
        r"<script\b[^>]*>.*?</script>", " ", raw_doc, flags=re.IGNORECASE | re.DOTALL
    )
    without_styles = re.sub(
        r"<style\b[^>]*>.*?</style>",
        " ",
        without_scripts,
        flags=re.IGNORECASE | re.DOTALL,
    )
    with_breaks = re.sub(
        r"</?(p|div|h1|h2|h3|h4|h5|h6|li|br|tr|section|article)[^>]*>",
        "\n",
        without_styles,
        flags=re.IGNORECASE,
    )
    text = re.sub(r"<[^>]+>", " ", with_breaks)
    text = html.unescape(text)
    text = re.sub(r"<[^>]+>", " ", text)
    text = re.sub(r"\s+", " ", text).strip()
    if len(text) > max_chars:
        text = text[:max_chars].rstrip() + "..."
    return title, text


def _build_web_summary(*, title: str, text: str, max_sentences: int = 4) -> str:
    cleaned = html.unescape(str(text or "").strip())
    cleaned = re.sub(r"<[^>]+>", " ", cleaned)
    cleaned = re.sub(r"\s+", " ", cleaned).strip()
    if not cleaned:
        return "I could access the page, but I could not extract readable text to summarize."

    # Keep summarization deterministic and dependency-free.
    sentences = re.split(r"(?<=[.!?])\s+", cleaned)
    sentences = [item.strip() for item in sentences if item and item.strip()]
    selected: list[str] = []
    seen: set[str] = set()
    for sentence in sentences:
        normalized = sentence.lower()
        if normalized in seen:
            continue
        seen.add(normalized)
        selected.append(sentence)
        if len(selected) >= max(1, min(8, int(max_sentences))):
            break

    if not selected:
        selected = [cleaned[:420].rstrip()]

    prefix = f"Page title: {title}. " if title else ""
    return prefix + " ".join(selected)


def _normalize_web_research_query(text: str) -> str:
    cleaned = " ".join(str(text or "").strip().split())
    cleaned = re.sub(
        r"^(hi|hello|hey)\s+mim\b[:,]?\s*", "", cleaned, flags=re.IGNORECASE
    )
    cleaned = re.sub(r"^mim\b[:,]?\s*", "", cleaned, flags=re.IGNORECASE)
    return cleaned.strip()


