def _initiative_status_from_resolution_metadata(
    metadata_json: dict[str, object] | None,
) -> dict[str, object]:
    metadata = metadata_json if isinstance(metadata_json, dict) else {}
    explicit_status = (
        metadata.get("initiative_status")
        if isinstance(metadata.get("initiative_status"), dict)
        else {}
    )
    program_status = (
        metadata.get("program_status")
        if isinstance(metadata.get("program_status"), dict)
        else {}
    )
    current_summary = str(metadata.get("current_recommendation_summary") or "").strip()

    if explicit_status:
        derived_status = dict(explicit_status)
        if not str(derived_status.get("summary") or "").strip() and current_summary:
            derived_status["summary"] = current_summary
        if not isinstance(derived_status.get("program_status"), dict) and program_status:
            derived_status["program_status"] = program_status
        return derived_status

    if program_status or current_summary:
        return {
            "summary": current_summary,
            "program_status": program_status,
        }

    return {}


def _to_execution_out(row: CapabilityExecution) -> dict:
    feedback = row.feedback_json if isinstance(row.feedback_json, dict) else {}
    strategy_plan = feedback.get("strategy_plan", {}) if isinstance(feedback.get("strategy_plan", {}), dict) else {}
    return {
        "execution_id": row.id,
        "input_event_id": row.input_event_id,
        "resolution_id": row.resolution_id,
        "goal_id": row.goal_id,
        "capability_name": row.capability_name,
        "arguments_json": row.arguments_json,
        "safety_mode": row.safety_mode,
        "requested_executor": row.requested_executor,
        "dispatch_decision": row.dispatch_decision,
        "trace_id": row.trace_id,
        "managed_scope": row.managed_scope,
        "status": row.status,
        "reason": row.reason,
        "feedback_json": feedback,
        "strategy_plan": strategy_plan,
        "execution_readiness": (
            feedback.get("execution_readiness", {})
            if isinstance(feedback.get("execution_readiness", {}), dict)
            else _json_dict(
                _json_dict(feedback.get("execution_policy_gate", {})).get("execution_readiness")
            )
        ),
        "execution_truth": (
            row.execution_truth_json
            if isinstance(row.execution_truth_json, dict)
            else {}
        ),
        "handoff_endpoint": f"/gateway/capabilities/executions/{row.id}/handoff",
        "created_at": row.created_at,
    }


def _ensure_request_id(metadata_json: object) -> tuple[dict[str, object], str]:
    metadata = dict(metadata_json) if isinstance(metadata_json, dict) else {}
    request_id = str(metadata.get("request_id") or "").strip()
    if not request_id:
        request_id = f"mim-request-{uuid.uuid4()}"
        metadata["request_id"] = request_id
    return metadata, request_id


def _compact_interface_text(value: object, limit: int = 160) -> str:
    return _compact_text(" ".join(str(value or "").strip().split()), limit)


def _mim_interface_understanding(
    *,
    event: InputEvent,
    resolution: InputEventResolution,
) -> str:
    goal_description = str(resolution.proposed_goal_description or "").strip()
    internal_intent = str(resolution.internal_intent or "").strip().lower()
    if internal_intent in {"create_goal", "execute_capability"} and goal_description:
        return _compact_interface_text(goal_description, 180)
    return _compact_interface_text(event.raw_input, 180)


def _mim_interface_status(
    *,
    resolution: InputEventResolution,
    execution: CapabilityExecution | None,
) -> str:
    resolution_meta = (
        resolution.metadata_json if isinstance(resolution.metadata_json, dict) else {}
    )
    status_override = str(
        resolution_meta.get("mim_interface_status_override") or ""
    ).strip()
    if status_override:
        return status_override
    tod_dispatch = (
        resolution_meta.get("tod_dispatch")
        if isinstance(resolution_meta.get("tod_dispatch"), dict)
        else {}
    )
    if tod_dispatch:
        dispatch_status = str(
            tod_dispatch.get("result_status") or tod_dispatch.get("request_status") or ""
        ).strip().lower()
        if dispatch_status in {"failed", "blocked", "error"}:
            return "blocked"
        if dispatch_status in {"accepted", "running", "pending", "recorded"}:
            return "doing"
        if dispatch_status in {"succeeded", "completed", "done"}:
            return "done"

    if execution is not None:
        execution_status = str(execution.status or "").strip().lower()
        if execution_status in {"failed", "blocked", "error"}:
            return "blocked"
        if execution_status in {"pending_confirmation"}:
            return "deferred"
        if execution_status in {"accepted", "running", "dispatched", "pending"}:
            return "doing"
        if execution_status in {"succeeded"}:
            return "done"

    outcome = str(resolution.outcome or "").strip().lower()
    if outcome == "blocked":
        return "blocked"
    if outcome == "requires_confirmation":
        return "deferred"
    return "done"


def _mim_interface_next_action(
    *,
    event: InputEvent,
    resolution: InputEventResolution,
    execution: CapabilityExecution | None,
) -> str:
    resolution_meta = (
        resolution.metadata_json if isinstance(resolution.metadata_json, dict) else {}
    )
    next_action_override = str(
        resolution_meta.get("mim_interface_next_action_override") or ""
    ).strip()
    if next_action_override:
        return next_action_override
    tod_dispatch = (
        resolution_meta.get("tod_dispatch")
        if isinstance(resolution_meta.get("tod_dispatch"), dict)
        else {}
    )
    if tod_dispatch:
        dispatch_kind = str(tod_dispatch.get("dispatch_kind") or "").strip().lower()
        if dispatch_kind == "bounded_bridge_warning_recommendation_request":
            return "dispatch one bounded TOD bridge-warning next-step recommendation request and surface TOD's result"
        if dispatch_kind == "bounded_bridge_warning_request":
            return "dispatch one bounded TOD bridge-warning explanation request and surface TOD's result"
        if dispatch_kind == "bounded_warnings_summary_request":
            return "dispatch one bounded TOD warnings-summary request and surface TOD's result"
        if dispatch_kind == "bounded_objective_summary_request":
            return "dispatch one bounded TOD current-objective summary request and surface TOD's result"
        if dispatch_kind == "bounded_recent_changes_request":
            return "dispatch one bounded TOD recent-changes summary request and surface TOD's result"
        return "dispatch one bounded TOD status request and surface TOD's result"

    if execution is not None:
        execution_status = str(execution.status or "").strip().lower()
        capability_name = _compact_interface_text(execution.capability_name, 96)
        if execution_status == "pending_confirmation":
            return "wait for explicit confirmation before dispatching the requested capability"
        if execution_status in {"dispatched", "accepted", "running", "pending"}:
            if capability_name:
                return f"hand off {capability_name} to TOD and track the result"
            return "hand off the approved request to TOD and track the result"
        if execution_status == "succeeded":
            return "report the completed execution result"
        if execution_status in {"failed", "blocked", "error"}:
            return "report the exact execution blocker"

    reason = str(resolution.reason or "").strip().lower()
    outcome = str(resolution.outcome or "").strip().lower()
    if outcome == "blocked":
        return "report the exact blocker for this request"
    if outcome == "requires_confirmation":
        if reason in {
            "conversation_optional_escalation",
            "conversation_optional_escalation_followup",
        }:
            return "wait for an explicit confirmation to create one bounded goal"
        return "wait for the missing detail needed to continue"
    if reason in {"conversation_precision_prompt", "conversation_precision_limit"}:
        return "wait for one specific question or action"
    if str(event.source or "").strip().lower() == "text":
        return "reply directly in this session"
    return "report the result of this request"


def _mim_interface_result(
    *,
    resolution: InputEventResolution,
    execution: CapabilityExecution | None,
    status: str,
) -> tuple[str, str]:
    resolution_meta = (
        resolution.metadata_json if isinstance(resolution.metadata_json, dict) else {}
    )
    result_override = str(
        resolution_meta.get("mim_interface_result_override") or ""
    ).strip()
    if result_override and status != "blocked":
        return result_override, ""

    communication_contract = (
        resolution_meta.get("communication_reply_contract")
        if isinstance(resolution_meta.get("communication_reply_contract"), dict)
        else {}
    )
    prompt_limit = (
        1000
        if communication_contract.get("response_mode") in {"active_project_context_grounded", "self_model_grounded"}
        else 240
    )
    prompt = _compact_interface_text(resolution.clarification_prompt, prompt_limit)
    if status == "blocked":
        blocker = prompt
        if not blocker and execution is not None:
            blocker = _compact_interface_text(execution.reason, 240)
        if not blocker:
            blocker = _compact_interface_text(resolution.reason, 240) or "Request blocked."
        return "", blocker

    if prompt:
        operator_status = _load_mim_tod_json_artifact(Path.cwd() / "runtime" / "shared" / "MIM_OPERATOR_STATUS.latest.json")
        append_operator_status_note = bool(
            communication_contract.get("append_operator_status_note")
        )
        if (
            append_operator_status_note
            and
            operator_status
            and not str(prompt).startswith("Current work:")
        ):
            phase = str(operator_status.get("current_phase") or "").strip().lower()
            objective = str(operator_status.get("current_objective_id") or "").strip()
            next_action = str(operator_status.get("next_safe_action") or "").strip()
            blocking_issue = str(operator_status.get("blocking_issue") or "").strip()
            if objective and phase in {"dispatched", "executing", "waiting", "blocked"}:
                status_note = (
                    f"Status note: {objective} is {phase}. "
                    f"{('Blocker: ' + blocking_issue + '. ') if blocking_issue else ''}"
                    f"Next: {next_action or 'I will update when the next result arrives.'}"
                )
                prompt = f"{prompt}\n\n{status_note}"
        return prompt, ""
    tod_dispatch = (
        resolution_meta.get("tod_dispatch")
        if isinstance(resolution_meta.get("tod_dispatch"), dict)
        else {}
    )
    if tod_dispatch:
        detail = _compact_interface_text(
            tod_dispatch.get("result_reason") or tod_dispatch.get("decision_detail") or "",
            240,
        )
        if status == "blocked":
            return "", detail or "TOD did not accept the bounded status request."
        return detail or "TOD returned one bounded status result.", ""

    if execution is not None:
        execution_status = str(execution.status or "").strip().lower()
        if execution_status in {"dispatched", "accepted", "running", "pending"}:
            return "The request has been accepted and is now in progress.", ""
        if execution_status == "succeeded":
            return "The requested action completed successfully.", ""
        if execution_status == "pending_confirmation":
            return "The request is waiting for explicit confirmation before dispatch.", ""

    outcome = str(resolution.outcome or "").strip().lower()
    if outcome == "requires_confirmation":
        return "I need one explicit confirmation or one missing detail before continuing.", ""
    if outcome == "store_only":
        return "I replied in session and did not dispatch any separate action.", ""
    return "Request processed.", ""


MIM_REVIEWABLE_ARTIFACT_SUFFIXES = {
    ".html": ("html_prototype", "text/html", "HTML prototype"),
    ".htm": ("html_prototype", "text/html", "HTML prototype"),
    ".md": ("document", "text/markdown", "Markdown document"),
    ".txt": ("document", "text/plain", "Text document"),
    ".json": ("data", "application/json", "JSON artifact"),
    ".csv": ("spreadsheet", "text/csv", "CSV spreadsheet"),
    ".png": ("image", "image/png", "Image"),
    ".jpg": ("image", "image/jpeg", "Image"),
    ".jpeg": ("image", "image/jpeg", "Image"),
    ".webp": ("image", "image/webp", "Image"),
}


def _mim_reviewable_artifact_query(raw_query: str) -> bool:
    query = " ".join(str(raw_query or "").strip().lower().split())
    if not query:
        return False
    return any(
        marker in query
        for marker in {
            "show me a sample",
            "show me the sample",
            "show me",
            "what does it look like",
            "what will it look like",
            "can i see it",
            "can i see",
            "do you have a sample",
            "have a sample",
            "see the sample",
            "see a sample",
            "open the sample",
            "show the prototype",
            "show me the prototype",
            "preview",
            "screenshot",
            "visual",
            "no card",
            "there is no card",
            "no link",
            "there is no link",
            "where is the card",
            "where is the link",
            "card below",
            "link below",
            "what card",
            "what link",
            "not showing",
        }
    )


def _mim_reviewable_artifact_score(path: Path, query: str) -> tuple[int, float]:
    name = path.name.lower()
    suffix = path.suffix.lower()
    suffix_priority = {
        ".html": 90,
        ".htm": 90,
        ".png": 80,
        ".jpg": 80,
        ".jpeg": 80,
        ".webp": 80,
        ".md": 70,
        ".txt": 60,
        ".csv": 55,
        ".json": 30,
    }.get(suffix, 0)
    name_score = 0
    if "homepage" in query or "home page" in query:
        name_score += 50 if "homepage" in name or "home_page" in name else 0
    if "prototype" in name or "sample" in name:
        name_score += 30
    if "brief" in name or "design" in name:
        name_score += 15
    if "status" in name or "heartbeat" in name or "dispatcher" in name:
        name_score -= 40
    return (suffix_priority + name_score, path.stat().st_mtime)


def _mim_find_reviewable_artifact(
    *,
    raw_query: str,
    shared_root: Path,
) -> Path | None:
    preferred = shared_root / "MIM_PUBLIC_HOMEPAGE_REIMAGINING_SAMPLE.latest.html"
    if preferred.exists() and preferred.is_file():
        return preferred
    candidates: list[Path] = []
    for path in shared_root.iterdir() if shared_root.exists() else []:
        if not path.is_file() or path.name.startswith("."):
            continue
        if path.suffix.lower() not in MIM_REVIEWABLE_ARTIFACT_SUFFIXES:
            continue
        if path.suffix.lower() == ".json" and not any(
            marker in path.name.lower()
            for marker in {"brief", "design", "prototype", "sample", "roadmap", "pricing", "catalog", "foundation"}
        ):
            continue
        candidates.append(path)
    if not candidates:
        return None
    query = " ".join(str(raw_query or "").strip().lower().split())
    return max(candidates, key=lambda path: _mim_reviewable_artifact_score(path, query))


def _looks_like_homepage_sample_feedback(text: str) -> bool:
    query = " ".join(str(text or "").strip().lower().split())
    if not query:
        return False
    homepage_terms = {
        "homepage",
        "home page",
        "sample page",
        "sample",
        "landing page",
        "hero",
        "talk to mim",
        "meet mim",
        "example project",
        "project cards",
        "trust section",
        "footer",
        "visual design",
        "animated background",
        "what mim can help create",
    }
    feedback_terms = {
        "too serious",
        "missing",
        "needs",
        "should",
        "i think",
        "i want",
        "better",
        "not yet",
        "review",
        "biggest thing",
        "add next",
        "move it",
        "dominant",
    }
    return any(term in query for term in homepage_terms) and any(
        term in query for term in feedback_terms
    )


def _homepage_feedback_points(text: str) -> list[str]:
    query = " ".join(str(text or "").strip().lower().split())
    candidates = [
        ("Add a Meet MIM personality section that explains what MIM does and why the user can start with an unfinished idea.", ("meet mim", "who is mim", "personality")),
        ("Replace tiny example pills with richer example project cards such as running app, robotics controller, and inventory platform.", ("example project", "project cards", "examples are too small", "running app", "robotics controller")),
        ("Make Talk To MIM and the conversation box the dominant product surface.", ("talk to mim", "conversation box", "dominant", "chatgpt")),
        ("Expose voice entry beside typing with a small microphone/talk control.", ("voice", "microphone", "mic", "talk", "type")),
        ("Move compliance checklist language to a warmer Trusted by Design section or footer.", ("trust", "privacy", "ai disclosure", "cookie", "footer", "trusted by design")),
        ("Add a subtle premium animated background so the page feels alive without becoming sci-fi.", ("animated", "background", "network", "constellation", "topology", "wow")),
        ("Add a What MIM Can Help Create grid covering apps, games, AI, robotics, web, mobile, analytics, and automation.", ("what mim can help create", "apps", "games", "robotics", "automation", "analytics")),
        ("Make MIM feel alive and available with an online/ready status, recent projects, and a clear invitation to start.", ("alive", "waiting for me", "mim is online", "mim is ready", "mim is available", "recent projects", "ready to start")),
        ("Make Talk To MIM the largest and brightest action on the page.", ("talk to mim button", "too small", "money button", "largest action", "brightest object")),
        ("Make the idea input taller so visitors can describe messy real-world problems, not just short app names.", ("input box", "taller", "2x", "ideas are messy", "fuel stations", "spreadsheets")),
        ("Warm up the hero copy so it speaks to ideas, frustrations, wishes, and half-finished concepts.", ("hero", "generic", "frustration", "wish", "half-finished", "something real")),
    ]
    points = [
        point
        for point, markers in candidates
        if any(marker in query for marker in markers)
    ]
    return points or [
        "Treat this as homepage sample feedback and revise the page toward MIM personality, stronger examples, a dominant conversation box, and clearer trust."
    ]


def _mim_homepage_sample_feedback_contract(
    raw_query: str,
    *,
    shared_root: Path | None = None,
) -> dict[str, object]:
    if not _looks_like_homepage_sample_feedback(raw_query):
        return {}
    root = shared_root or (Path.cwd() / "runtime" / "shared")
    points = _homepage_feedback_points(raw_query)
    generated_at = _mim_tod_stage_timestamp()
    feedback_path = root / "MIM_PUBLIC_HOMEPAGE_REIMAGINING_FEEDBACK.latest.json"
    payload = {
        "packet_type": "mim-public-homepage-reimagining-feedback-v1",
        "generated_at": generated_at,
        "objective_id": "MIM-PUBLIC-HOMEPAGE-REIMAGINING-V1",
        "feedback_summary": "Homepage sample needs more MIM personality, stronger creation examples, and a more dominant conversation-first product surface.",
        "revision_points": points,
        "recommended_next_action": "Revise the homepage prototype and return a new reviewable sample card in this chat.",
        "source": "mim_chat_design_feedback",
    }
    try:
        root.mkdir(parents=True, exist_ok=True)
        feedback_path.write_text(json.dumps(payload, indent=2, sort_keys=True), encoding="utf-8")
    except Exception:
        pass

    revision_contract = _mim_homepage_revision_contract(
        "revise homepage sample from captured feedback",
        shared_root=root,
        force=True,
    )
    attachment = (
        revision_contract.get("attachment")
        if isinstance(revision_contract.get("attachment"), dict)
        else None
    )
    links = (
        revision_contract.get("links")
        if isinstance(revision_contract.get("links"), list)
        else []
    )
    bullets = " ".join(f"{index}. {point}" for index, point in enumerate(points[:5], start=1))
    reply_text = (
        "You're right. I treated the sample like a polished software consultant page, but it needs to feel more like me as a creation partner with personality. "
        f"Here's what I changed right now: {bullets} "
        "I created an updated visual sample and attached it below so you can review it immediately."
    )
    return {
        "reply_text": reply_text,
        "response_mode": "homepage_sample_feedback_applied",
        "composer_mode": "deterministic_artifact",
        "should_store_memory": True,
        "memory_topics": ["homepage_reimagining", "design_feedback", "mim_personality"],
        "memory_people": ["Dave"],
        "memory_events": [],
        "memory_experiences": [],
        "feedback_artifact": str(feedback_path),
        "feedback": payload,
        "attachment": attachment,
        "links": links,
    }


def _looks_like_homepage_revision_request(
    text: str,
    *,
    shared_root: Path | None = None,
) -> bool:
    query = " ".join(str(text or "").strip().lower().split())
    if not query:
        return False
    root = shared_root or (Path.cwd() / "runtime" / "shared")
    feedback_path = root / "MIM_PUBLIC_HOMEPAGE_REIMAGINING_FEEDBACK.latest.json"
    if not feedback_path.exists():
        return False
    action_terms = (
        "yes continue",
        "continue",
        "implement",
        "impliment",
        "revise",
        "update",
        "make the changes",
        "apply the changes",
        "provide an updated sample",
        "updated sample",
        "new sample",
    )
    artifact_terms = (
        "homepage",
        "home page",
        "prototype",
        "sample",
        "changes",
        "visual",
        "page",
    )
    return any(term in query for term in action_terms) and any(
        term in query for term in artifact_terms
    )


