def _is_action_request_query(normalized_query: str) -> bool:
    query = str(normalized_query or "").strip().lower()
    if not query:
        return False

    non_action_prefixes = (
        "what ",
        "how ",
        "why ",
        "when ",
        "where ",
        "who ",
        "are ",
        "is ",
        "do you ",
        "can you ",
        "could you ",
        "would you ",
        "will you ",
        "should you ",
        "status",
        "check status",
    )
    if query.startswith(non_action_prefixes):
        return False

    action_prefixes = (
        "start ",
        "run ",
        "execute ",
        "launch ",
        "queue ",
        "open ",
        "create ",
        "post ",
        "send ",
        "scan ",
        "move ",
        "deploy ",
    )
    return query.startswith(action_prefixes)


def _action_confirmation_response(normalized_query: str) -> str:
    action_summary = _compact_text(normalized_query.rstrip(".?"), 96)
    return (
        f"Before I treat that as an action: please confirm you want me to '{action_summary}'. "
        "Say confirm to approve it, revise it in one sentence, or cancel it."
    )


def _object_query_tokens(text: str) -> set[str]:
    normalized = _normalize_conversation_query(text)
    stopwords = {
        "a",
        "an",
        "and",
        "at",
        "for",
        "go",
        "i",
        "in",
        "is",
        "it",
        "me",
        "my",
        "now",
        "of",
        "on",
        "our",
        "s",
        "that",
        "the",
        "their",
        "there",
        "they",
        "this",
        "to",
        "we",
        "what",
        "where",
        "who",
        "your",
    }
    return {
        token
        for token in normalized.split()
        if token and token not in stopwords and len(token) > 1
    }


def _extract_object_question_target(normalized_query: str) -> tuple[str, str]:
    patterns = [
        ("location", r"\bwhere is (.+)$"),
        ("location", r"\bwhere did (.+?) go$"),
        ("purpose", r"\bwhat is (.+?) for$"),
        ("purpose", r"\bwhat is the purpose of (.+)$"),
        ("ownership", r"\bwho owns (.+)$"),
        ("ownership", r"\bwho does (.+?) belong to$"),
    ]
    for question_type, pattern in patterns:
        match = re.search(pattern, normalized_query)
        if not match:
            continue
        target = " ".join(str(match.group(1) or "").strip().split())
        target = re.sub(r"^(the|a|an|this|that|my|our|your)\s+", "", target).strip()
        if len(_object_query_tokens(target)) >= 1:
            return question_type, target
    return "", ""


def _object_memory_aliases(row: WorkspaceObjectMemory) -> set[str]:
    metadata = row.metadata_json if isinstance(row.metadata_json, dict) else {}
    owner = str(metadata.get("owner") or "").strip()
    aliases = {str(row.canonical_name or "").strip()}
    if isinstance(row.candidate_labels, list):
        aliases.update(
            str(item).strip() for item in row.candidate_labels if str(item).strip()
        )
    aliases.update(
        str(metadata.get(key) or "").strip()
        for key in ["description", "purpose", "category"]
        if str(metadata.get(key) or "").strip()
    )
    if owner:
        current_aliases = [alias for alias in aliases if alias]
        aliases.add(owner)
        for alias in current_aliases:
            aliases.add(f"{owner} {alias}")
            aliases.add(f"{owner} s {alias}")
    return {alias for alias in aliases if alias}


def _score_object_memory_match(target: str, row: WorkspaceObjectMemory) -> float:
    target_normalized = _normalize_conversation_query(target)
    target_tokens = _object_query_tokens(target_normalized)
    if not target_tokens:
        return 0.0

    best_score = 0.0
    for alias in _object_memory_aliases(row):
        alias_normalized = _normalize_conversation_query(alias)
        if not alias_normalized:
            continue
        if alias_normalized == target_normalized:
            return 1.0
        alias_tokens = _object_query_tokens(alias_normalized)
        if not alias_tokens:
            continue
        overlap = len(target_tokens & alias_tokens) / float(len(target_tokens))
        if overlap > best_score:
            best_score = overlap
        if len(target_tokens) > 1 and (
            alias_normalized.endswith(target_normalized)
            or target_normalized.endswith(alias_normalized)
        ):
            best_score = max(best_score, 0.95)

    metadata = row.metadata_json if isinstance(row.metadata_json, dict) else {}
    owner = str(metadata.get("owner") or "").strip()
    if owner and _contains_word(target_normalized, owner):
        best_score = min(1.0, best_score + 0.1)
    return best_score


async def _object_memory_context_for_query(
    db: AsyncSession, user_input: str
) -> dict[str, object]:
    normalized_query = _normalize_conversation_query(user_input)
    question_type, target = _extract_object_question_target(normalized_query)
    if not question_type or not target:
        return {}

    rows = (
        (
            await db.execute(
                select(WorkspaceObjectMemory)
                .order_by(
                    WorkspaceObjectMemory.last_seen_at.desc(),
                    WorkspaceObjectMemory.id.desc(),
                )
                .limit(40)
            )
        )
        .scalars()
        .all()
    )
    best_row: WorkspaceObjectMemory | None = None
    best_score = 0.0
    for row in rows:
        score = _score_object_memory_match(target, row)
        if score > best_score:
            best_score = score
            best_row = row

    if best_row is None or best_score < 0.74:
        return {}

    metadata = (
        best_row.metadata_json if isinstance(best_row.metadata_json, dict) else {}
    )
    return {
        "memory_object_query_type": question_type,
        "memory_object_reference": target,
        "memory_object_label": str(best_row.canonical_name or "").strip(),
        "memory_object_zone": str(best_row.zone or "").strip(),
        "memory_object_status": str(best_row.status or "").strip(),
        "memory_object_owner": str(metadata.get("owner") or "").strip(),
        "memory_object_purpose": str(metadata.get("purpose") or "").strip(),
        "memory_object_description": str(metadata.get("description") or "").strip(),
        "memory_object_expected_home_zone": str(
            metadata.get("expected_home_zone")
            or metadata.get("expected_zone")
            or metadata.get("home_zone")
            or ""
        ).strip(),
    }


async def _latest_camera_observation_context(db: AsyncSession) -> dict[str, object]:
    camera_rows = (
        (
            await db.execute(
                select(WorkspacePerceptionSource)
                .where(WorkspacePerceptionSource.source_type == "camera")
                .order_by(
                    WorkspacePerceptionSource.last_seen_at.desc(),
                    WorkspacePerceptionSource.id.desc(),
                )
                .limit(6)
            )
        )
        .scalars()
        .all()
    )
    observations = collect_fresh_camera_observations(
        camera_rows,
        now=datetime.now(timezone.utc),
        stale_seconds=max(PERCEPTION_STALE_SECONDS, 90),
    )
    summary = summarize_camera_observations(observations)
    return {
        "camera_label": str(summary.get("primary_label", "")).strip(),
        "camera_confidence": float(summary.get("primary_confidence", 0.0) or 0.0),
        "camera_zone": str(summary.get("primary_zone", "")).strip(),
        "camera_scene_summary": str(summary.get("summary", "")).strip(),
        "camera_source_count": int(summary.get("source_count", 0) or 0),
        "camera_observation_count": int(summary.get("observation_count", 0) or 0),
        "camera_labels": list(summary.get("labels", []))
        if isinstance(summary.get("labels", []), list)
        else [],
    }


def _object_inquiry_questions(
    label_raw: str, missing_fields: list[str] | None = None
) -> list[str]:
    label = str(label_raw or "that object").strip() or "that object"
    fields = [
        str(item).strip().lower()
        for item in (missing_fields or [])
        if str(item).strip()
    ]
    if not fields:
        fields = ["description", "purpose"]

    questions: list[str] = []
    if "description" in fields:
        questions.append(f"What is {label}?")
    if "purpose" in fields:
        questions.append(f"What does {label} do?")
    if "owner" in fields:
        questions.append(f"Who owns {label}?")
    if "expected_home_zone" in fields:
        questions.append(f"Where should {label} normally live?")
    if "category" in fields:
        questions.append(f"What kind of object is {label}?")
    if "meaning" in fields or "explanation" in fields:
        questions.append(f"What should I understand about {label}?")
    if "user_notes" in fields:
        questions.append(f"Any notes I should remember about {label}?")
    questions.append("Explain more if needed.")
    return questions


def _next_object_inquiry_missing_fields(metadata: dict[str, object]) -> list[str]:
    stages = [
        ["description", "purpose"],
        ["owner", "expected_home_zone"],
        ["category", "meaning", "user_notes"],
    ]
    for stage in stages:
        missing = [
            field for field in stage if not str(metadata.get(field) or "").strip()
        ]
        if missing:
            return missing
    return []


def _object_inquiry_prompt(context: dict[str, object]) -> str:
    label = str(context.get("object_label") or "that object").strip() or "that object"
    zone = str(context.get("object_zone") or "").strip()
    description = str(context.get("object_description") or "").strip()
    missing_fields = [
        str(item).strip().lower()
        for item in (context.get("missing_fields") or [])
        if str(item).strip()
    ]
    questions = _object_inquiry_questions(label, missing_fields)
    scene_summary = str(context.get("camera_scene_summary") or "").strip()
    source_count = int(context.get("camera_source_count") or 0)
    confidence = float(context.get("camera_confidence") or 0.0)

    if scene_summary and source_count > 1:
        if confidence > 0.0:
            seen_prefix = (
                f"I can currently see {scene_summary}. Primary confidence is "
                f"{confidence:.2f}."
            )
        else:
            seen_prefix = f"I can currently see {scene_summary}."
    else:
        zone_suffix = f" in {zone}" if zone else ""
        if confidence > 0.0:
            seen_prefix = (
                f"I can currently see {label}{zone_suffix} on camera with confidence "
                f"{confidence:.2f}."
            )
        else:
            seen_prefix = f"I can currently see {label}{zone_suffix} on camera."

    if description and missing_fields == ["purpose"]:
        knowledge_gap = (
            f" I know {label} is {description}, but I do not know what it does yet."
        )
    elif description:
        knowledge_gap = (
            f" I know {label} is {description}, but I still need more semantic detail."
        )
    else:
        knowledge_gap = f" I do not know what {label} is yet."
    return f"{seen_prefix}{knowledge_gap} {' '.join(questions)}"


def _camera_observation_response(context: dict[str, object]) -> str:
    camera_label = str(context.get("camera_label") or "").strip()
    camera_zone = str(context.get("camera_zone") or "").strip()
    camera_confidence = float(context.get("camera_confidence") or 0.0)
    camera_scene_summary = str(context.get("camera_scene_summary") or "").strip()
    camera_source_count = int(context.get("camera_source_count") or 0)
    inquiry_prompt = str(context.get("camera_object_inquiry_prompt") or "").strip()
    if not camera_label:
        return ""
    if inquiry_prompt:
        return inquiry_prompt
    if camera_scene_summary and camera_source_count > 1:
        if camera_confidence > 0.0:
            return (
                f"I can currently see {camera_scene_summary}. "
                f"Primary confidence is {camera_confidence:.2f}."
            )
        return f"I can currently see {camera_scene_summary}."
    zone_suffix = f" in {camera_zone}" if camera_zone else ""
    if camera_confidence > 0.0:
        return (
            f"I can currently see {camera_label}{zone_suffix} on camera "
            f"with confidence {camera_confidence:.2f}."
        )
    return f"I can currently see {camera_label}{zone_suffix} on camera."


def _camera_presence_response(context: dict[str, object]) -> str:
    observation = _camera_observation_response(context)
    if observation:
        return (
            f"{observation} I cannot confirm from this camera view alone "
            "that the visible subject is you."
        )
    return (
        "I can only answer that from current camera observations, and I do not "
        "have a clear camera observation right now."
    )


async def _find_workspace_object_by_label(
    db: AsyncSession,
    *,
    label: str,
    zone: str = "",
) -> WorkspaceObjectMemory | None:
    target_label = str(label or "").strip()
    if not target_label:
        return None

    rows = (
        (
            await db.execute(
                select(WorkspaceObjectMemory)
                .order_by(
                    WorkspaceObjectMemory.last_seen_at.desc(),
                    WorkspaceObjectMemory.id.desc(),
                )
                .limit(80)
            )
        )
        .scalars()
        .all()
    )

    best_row: WorkspaceObjectMemory | None = None
    best_score = 0.0
    normalized_zone = str(zone or "").strip().lower()
    for row in rows:
        score = _score_object_memory_match(target_label, row)
        if normalized_zone and str(row.zone or "").strip().lower() == normalized_zone:
            score = min(1.0, score + 0.08)
        if score > best_score:
            best_score = score
            best_row = row

    if best_row is None or best_score < 0.74:
        return None
    return best_row


async def _camera_object_inquiry_context(
    db: AsyncSession,
    *,
    camera_context: dict[str, object],
) -> dict[str, object]:
    label = str(camera_context.get("camera_label") or "").strip()
    if not label:
        return {}

    zone = str(camera_context.get("camera_zone") or "").strip()
    object_row = await _find_workspace_object_by_label(db, label=label, zone=zone)
    if object_row is None:
        return {}

    metadata = (
        object_row.metadata_json if isinstance(object_row.metadata_json, dict) else {}
    )
    description = str(metadata.get("description") or "").strip()
    missing_fields = _next_object_inquiry_missing_fields(metadata)
    if not missing_fields:
        return {}

    inquiry_context = {
        "status": "pending",
        "object_memory_id": int(object_row.id),
        "object_label": str(object_row.canonical_name or label).strip() or label,
        "object_zone": str(object_row.zone or zone).strip(),
        "object_description": description,
        "missing_fields": missing_fields,
        "camera_scene_summary": str(
            camera_context.get("camera_scene_summary") or ""
        ).strip(),
        "camera_source_count": int(camera_context.get("camera_source_count") or 0),
        "camera_confidence": float(camera_context.get("camera_confidence") or 0.0),
    }
    inquiry_context["inquiry_questions"] = _object_inquiry_questions(
        inquiry_context["object_label"],
        missing_fields,
    )
    inquiry_context["inquiry_prompt"] = _object_inquiry_prompt(inquiry_context)
    return inquiry_context


def _extract_object_inquiry_reply(
    text: str,
    *,
    label: str,
    missing_fields: list[str] | None = None,
) -> dict[str, str]:
    raw = str(text or "").strip()
    if not raw:
        return {}

    fields = {
        str(item).strip().lower()
        for item in (missing_fields or [])
        if str(item).strip()
    }
    if not fields:
        fields = {"description", "purpose", "owner", "expected_home_zone"}

    def _normalize_clause(value: str) -> str:
        clause = _normalize_conversation_query(value)
        clause = re.sub(
            r"^(?:actually|well|uh|um|hmm|sorry|ok|okay|so|right)\b[\s,]*",
            "",
            clause,
        ).strip()
        clause = re.sub(r"\bit\s+is\s+like\s+", "it is ", clause)
        clause = re.sub(r"\bit\s+s\s+like\s+", "it is ", clause)
        clause = re.sub(r"\bit\s+is\s+kind\s+of\s+", "it is ", clause)
        clause = re.sub(r"\bit\s+s\s+kind\s+of\s+", "it is ", clause)
        return clause.strip()

    normalized_label = _normalize_conversation_query(label)
    clauses = [
        _normalize_clause(part)
        for part in re.split(r"[\.!?;]+", raw)
        if str(part).strip()
    ]
    if not clauses:
        clauses = [_normalize_clause(raw)]

    result: dict[str, str] = {}
    subject_pattern = r"(?:it|that|this|the object|the item|the thing)"
    if normalized_label:
        subject_pattern = rf"(?:{subject_pattern}|{re.escape(normalized_label)})"

    purpose_patterns = [
        rf"^{subject_pattern}\s+(?:is\s+used\s+for|is\s+for|used\s+for)\s+(.+)$",
        rf"^{subject_pattern}\s+(charges|holds|stores|powers|connects|mounts|supports|measures|cuts|scans|carries|docks)\s+(.+)$",
        r"^for\s+(.+)$",
    ]
    description_patterns = [
        rf"^{subject_pattern}\s+(?:is|s)\s+(.+)$",
        r"^(?:a|an|the)\s+(.+)$",
    ]
    owner_patterns = [
        rf"^{subject_pattern}\s+(?:belongs to|is owned by)\s+(.+)$",
        rf"^(?:owner is|owned by)\s+(.+)$",
        rf"^(.+?)\s+owns\s+{subject_pattern}$",
        rf"^it is\s+(.+?)\s+s$",
    ]
    home_zone_patterns = [
        rf"^{subject_pattern}\s+(?:should live|lives|stays|belongs)\s+(?:in|on|at)\s+(.+)$",
        rf"^(?:home is|keep it|store it)\s+(?:in|on|at)\s+(.+)$",
        rf"^(?:it should go|it goes)\s+(?:in|on|at)\s+(.+)$",
    ]
    category_patterns = [
        rf"^(?:category is|type is|kind is)\s+(.+)$",
        rf"^{subject_pattern}\s+(?:is a kind of|is kind of|counts as)\s+(.+)$",
    ]
    meaning_patterns = [
        rf"^(?:meaning is|it means|that means)\s+(.+)$",
        rf"^(?:it tells me|it tells us|it indicates|it shows)\s+(.+)$",
    ]
    user_note_patterns = [
        rf"^(?:note that|remember that|user note|note)\s+(.+)$",
        rf"^(?:keep in mind|please remember)\s+(.+)$",
    ]
    explanation_patterns = [
        rf"^(?:explanation is|more detail is|more context is)\s+(.+)$",
        rf"^(?:explain|more detail|more context)\s+(.+)$",
    ]

    def _normalize_owner(value: str) -> str:
        owner = " ".join(str(value or "").split()).strip(" .'\"")
        owner = re.sub(r"\bnow\b$", "", owner).strip(" .'\"")
        if not owner:
            return ""
        if owner.islower():
            owner = owner.title()
        return owner

    def _normalize_home_zone(value: str) -> str:
        zone = " ".join(str(value or "").split()).strip(" .'\"")
        zone = re.sub(r"^(the)\s+", "", zone).strip()
        return zone

    def _normalize_semantic_phrase(value: str) -> str:
        return " ".join(str(value or "").split()).strip(" .'\"")

    def _normalize_description(value: str) -> str:
        description = _normalize_semantic_phrase(value)
        description = re.sub(r"^(?:like|kind of|sort of)\s+", "", description).strip()
        description = re.sub(r"^(?:a|an)\s+kind\s+of\s+", "", description).strip()
        return description

    for clause in clauses:
        if not clause:
            continue
        if "purpose" in fields and "purpose" not in result:
            for pattern in purpose_patterns:
                match = re.match(pattern, clause)
                if not match:
                    continue
                if len(match.groups()) == 2:
                    verb = str(match.group(1) or "").strip()
                    tail = str(match.group(2) or "").strip()
                    purpose = " ".join(part for part in [verb, tail] if part).strip()
                else:
                    purpose = str(match.group(1) or "").strip()
                purpose = re.sub(r"^(to\s+)?", "", purpose).strip()
                if purpose:
                    result["purpose"] = purpose
                    break

        if "description" in fields and "description" not in result:
            for pattern in description_patterns:
                match = re.match(pattern, clause)
                if not match:
                    continue
                description = _normalize_description(str(match.group(1) or ""))
                description = re.split(
                    r"\b(?:used\s+for|for|because|which)\b", description, maxsplit=1
                )[0].strip()
                if description and not description.startswith(
                    ("charging ", "to charge ")
                ):
                    result["description"] = description
                    break

        if "owner" in fields and "owner" not in result:
            for pattern in owner_patterns:
                match = re.match(pattern, clause)
                if not match:
                    continue
                owner = _normalize_owner(str(match.group(1) or ""))
                if owner and owner not in {"it", "this", "that"}:
                    result["owner"] = owner
                    break

        if "expected_home_zone" in fields and "expected_home_zone" not in result:
            for pattern in home_zone_patterns:
                match = re.match(pattern, clause)
                if not match:
                    continue
                zone = _normalize_home_zone(str(match.group(1) or ""))
                if zone:
                    result["expected_home_zone"] = zone
                    break

        if "category" in fields and "category" not in result:
            for pattern in category_patterns:
                match = re.match(pattern, clause)
                if not match:
                    continue
                category = _normalize_semantic_phrase(str(match.group(1) or ""))
                if category:
                    result["category"] = category
                    break

        if "meaning" in fields and "meaning" not in result:
            for pattern in meaning_patterns:
                match = re.match(pattern, clause)
                if not match:
                    continue
                meaning = _normalize_semantic_phrase(str(match.group(1) or ""))
                if meaning:
                    result["meaning"] = meaning
                    break

        if "user_notes" in fields and "user_notes" not in result:
            for pattern in user_note_patterns:
                match = re.match(pattern, clause)
                if not match:
                    continue
                note = _normalize_semantic_phrase(str(match.group(1) or ""))
                if note:
                    result["user_notes"] = note
                    break

        if "explanation" in fields and "explanation" not in result:
            for pattern in explanation_patterns:
                match = re.match(pattern, clause)
                if not match:
                    continue
                explanation = _normalize_semantic_phrase(str(match.group(1) or ""))
                if explanation:
                    result["explanation"] = explanation
                    break

    normalized_raw = _normalize_conversation_query(raw)
    if "description" in fields and "description" not in result:
        tokens = normalized_raw.split()
        if (
            0 < len(tokens) <= 6
            and not _looks_like_question_text(raw)
            and not any(
                token in normalized_raw
                for token in [
                    "belongs to",
                    "owned by",
                    "should live",
                    "lives in",
                    "stays in",
                    "category is",
                    "it means",
                    "note that",
                ]
            )
        ):
            result["description"] = normalized_raw

    return result


def _looks_like_object_correction(text: str) -> bool:
    normalized = _normalize_conversation_query(text)
    if not normalized:
        return False
    return bool(
        re.search(r"\b(?:actually|correction|update|instead|rather|no)\b", normalized)
    )


def _object_inquiry_extraction_fields(
    metadata: dict[str, object],
    missing_fields: list[str] | None,
    user_input: str,
) -> list[str]:
    fields = [
        str(item).strip().lower()
        for item in (missing_fields or [])
        if str(item).strip()
    ]
    if not _looks_like_object_correction(user_input):
        return fields

    correction_candidates = [
        "description",
        "purpose",
        "owner",
        "expected_home_zone",
        "category",
        "meaning",
        "user_notes",
    ]
    for field in correction_candidates:
        if str(metadata.get(field) or "").strip() and field not in fields:
            fields.append(field)
    return fields


async def _learn_from_object_inquiry_reply(
    db: AsyncSession,
    *,
    user_input: str,
    inquiry_context: dict[str, object] | None,
) -> tuple[str, dict[str, object]]:
    context = inquiry_context if isinstance(inquiry_context, dict) else {}
    if str(context.get("status") or "").strip().lower() != "pending":
        return "", {}

    object_memory_id = int(context.get("object_memory_id") or 0)
    if object_memory_id <= 0:
        return "", {}

    object_row = await db.get(WorkspaceObjectMemory, object_memory_id)
    if object_row is None:
        return "", {}

    missing_fields = [
        str(item).strip().lower()
        for item in (context.get("missing_fields") or [])
        if str(item).strip()
    ]
    metadata = (
        object_row.metadata_json if isinstance(object_row.metadata_json, dict) else {}
    )
    extraction_fields = _object_inquiry_extraction_fields(
        metadata,
        missing_fields,
        user_input,
    )
    extracted = _extract_object_inquiry_reply(
        user_input,
        label=str(context.get("object_label") or object_row.canonical_name or "object"),
        missing_fields=extraction_fields,
    )
    if not extracted:
        return "", {}

    updated_metadata = {**metadata, **extracted}
    object_row.metadata_json = updated_metadata
    await db.flush()

    remaining_fields = _next_object_inquiry_missing_fields(updated_metadata)
    next_context = {
        "status": "resolved" if not remaining_fields else "pending",
        "object_memory_id": int(object_row.id),
        "object_label": str(
            object_row.canonical_name or context.get("object_label") or "object"
        ).strip(),
        "object_zone": str(object_row.zone or context.get("object_zone") or "").strip(),
        "object_description": str(updated_metadata.get("description") or "").strip(),
        "missing_fields": remaining_fields,
    }
    if remaining_fields:
        next_context["inquiry_questions"] = _object_inquiry_questions(
            next_context["object_label"],
            remaining_fields,
        )
        next_context["inquiry_prompt"] = _object_inquiry_prompt(next_context)

    label = next_context["object_label"]
    learned_bits: list[str] = []
    if str(updated_metadata.get("description") or "").strip():
        learned_bits.append(
            f"{label} is {str(updated_metadata.get('description')).strip()}"
        )
    if str(updated_metadata.get("purpose") or "").strip():
        learned_bits.append(
            f"{label} is used for {str(updated_metadata.get('purpose')).strip()}"
        )
    if str(updated_metadata.get("owner") or "").strip():
        learned_bits.append(
            f"{label} belongs to {str(updated_metadata.get('owner')).strip()}"
        )
    if str(updated_metadata.get("expected_home_zone") or "").strip():
        learned_bits.append(
            f"{label} should normally live in {str(updated_metadata.get('expected_home_zone')).strip()}"
        )
    if str(updated_metadata.get("category") or "").strip():
        learned_bits.append(
            f"{label} is categorized as {str(updated_metadata.get('category')).strip()}"
        )
    if str(updated_metadata.get("meaning") or "").strip():
        learned_bits.append(
            f"{label} means {str(updated_metadata.get('meaning')).strip()}"
        )
    if str(updated_metadata.get("user_notes") or "").strip():
        learned_bits.append(
            f"note for {label}: {str(updated_metadata.get('user_notes')).strip()}"
        )

    if remaining_fields:
        if learned_bits:
            prefix = f"Got it. I will remember that {' and '.join(learned_bits)}."
        else:
            prefix = f"Got it. I will remember what you shared about {label}."
        return f"{prefix} {next_context['inquiry_prompt']}", next_context

    return f"Got it. I will remember that {' and '.join(learned_bits)}.", next_context


def _conversation_topic_key(normalized_query: str, response: str = "") -> str:
    query = str(normalized_query or "").strip().lower()
    prompt = str(response or "").strip().lower()

    if prompt.startswith("i cannot share all private runtime details"):
        return "safety_boundary"
    if prompt.startswith("i cannot claim an external step already happened"):
        return "safety_boundary"
    if prompt.startswith("i cannot help with unsafe or risky operations"):
        return "safety_boundary"
    if prompt.startswith("i cannot choose unspecified external actions"):
        return "safety_boundary"
    if _is_pause_control_query(query) or prompt.startswith("paused. the pending action"):
        return "interrupt_control"
    if _is_resume_control_query(query) or prompt.startswith("resumed at the conversation layer"):
        return "interrupt_control"
    if _is_cancel_control_query(query) or prompt.startswith("cancelled. i will not treat"):
        return "interrupt_control"
    if _is_interruption_query(query) or prompt.startswith("understood. i stopped"):
        return "interrupt_control"
    if prompt.startswith("before i treat that as an action:"):
        return "action_confirmation"
    if (
        "technical framing:" in prompt
        or "plan of action:" in prompt
        or prompt.startswith("i researched step ")
        or prompt.startswith("i refreshed step ")
    ):
        return "technical_research"
    if "i researched the web for '" in prompt:
        return "web_research"
    if any(
        token in query for token in {"tod status", "how is tod", "tod healthy"}
    ) or prompt.startswith("tod status:"):
        return "tod_status"
    if (
        any(
            token in query
            for token in {
                "runtime health",
                "runtime status",
                "how is runtime health",
                "how is the runtime doing",
                "how is runtime doing",
            }
        )
        or prompt.startswith("runtime health:")
        or prompt.startswith("current status:")
    ):
        return "status"
    if (
        any(
            token in query
            for token in {
                "what is the system",
                "what is our system",
                "what's the system",
                "what's our system",
                "our system",
                "define the system",
            }
        )
        or "the system is mim plus tod" in prompt
    ):
        return "system"
    if (
        any(
            token in query
            for token in {
                "continue automatically",
                "act automatically",
                "keep going automatically",
                "proceed automatically",
                "automatic",
                "autonomy",
                "automatic right now",
                "autonomy right now",
                "what is your autonomy",
                "what is your autonomy status",
            }
        )
        or prompt.startswith("automatic continuation is limited")
    ):
        return "lightweight_autonomy"
    if (
        any(
            token in query
            for token in {
                "give feedback",
                "how do i give feedback",
                "what feedback do you need",
                "feedback loop",
                "feedback for you",
            }
        )
        or prompt.startswith("Give feedback in one sentence:")
    ):
        return "human_feedback"
    if (
        any(
            token in query
            for token in {
                "system stable",
                "how stable is the system",
                "system stability",
                "are you stable",
                "stability guard",
                "stability right now",
            }
        )
        or prompt.startswith("Stability guard:")
    ):
        return "system_stability"
    if (
        any(
            token in query
            for token in {
                "what is our objective",
                "current objective",
                "active objective",
                "what are you working on",
                "what are we working on",
                "what should we work on",
                "work on today",
            }
        )
        or "current objective focus" in prompt
    ):
        return "objective"
    if (
        _is_self_evolution_next_work_query(query)
        or prompt.startswith("next i would work on ")
        or "operator command:" in prompt
    ):
        return "self_evolution"
    if (
        any(
            token in query
            for token in {
                "what are we working on",
                "what should we prioritize",
                "prioritize next",
                "what should i do first",
                "what is next",
            }
        )
        or "top priority today" in prompt
    ):
        return "priorities"
    if (
        any(token in query for token in {"your mission", "primary mission"})
        or "my primary mission" in prompt
    ):
        return "mission"
    if (
        any(token in query for token in {"top risk", "biggest risk", "main risk"})
        or "top risk is" in prompt
    ):
        return "risk"
    if (
        any(
            token in query
            for token in {"reduce that risk", "reduce the risk", "lower that risk"}
        )
        or "reduce that risk with" in prompt
    ):
        return "risk_reduction"
    if (
        any(
            token in query
            for token in {"what can you do", "capabilities", "help", "your function"}
        )
        or "i can chat with you" in prompt
    ):
        return "capabilities"
    if (
        any(
            token in query
            for token in {
                "browse the web",
                "search the web",
                "look up",
                "research",
                "best brand",
                "proven",
                "compare",
            }
        )
        or "i researched the web for '" in prompt
    ):
        return "web_research"
    if "weather" in query or "live weather data" in prompt:
        return "weather"
    if (
        any(
            token in query
            for token in {
                "create an application",
                "build an application",
                "create app",
                "build app",
                "start a project",
            }
        )
        or "scope the application" in prompt
    ):
        return "project_planning"
    if (
        _looks_like_development_integration_query(query)
        or prompt.startswith("next action: inspect the existing mim_wall app")
        or prompt.startswith("next action: inspect the existing app against the current interface")
        or prompt.startswith("next action: inspect the closest existing asset")
    ):
        return "development_integration"
    if "news" in query or "top ai and tech themes today" in prompt:
        return "news"
    return "general"


async def _get_recent_text_conversation_context(
    db: AsyncSession,
    *,
    session_id: str,
    actor_name: str = DEFAULT_USER_ID,
    exclude_event_id: int | None = None,
    limit: int = 8,
) -> dict:
    remembered_context = await _load_remembered_conversation_context(
        db=db,
        actor_name=actor_name,
    )
    normalized_session = str(session_id or "").strip()
    if not normalized_session:
        return _merge_conversation_context_with_memory(
            _empty_recent_text_conversation_context(),
            remembered_context,
        )

    interface_session = await get_interface_session(
        session_key=normalized_session,
        db=db,
    )
    if interface_session is not None:
        session_context = _normalize_conversation_session_context(
            normalized_session,
            interface_session.context_json
            if isinstance(interface_session.context_json, dict)
            else {},
        )
        if exclude_event_id is None or int(session_context.get("last_input_event_id") or 0) != int(exclude_event_id):
            return _merge_conversation_context_with_memory({
                "turn_count": int(session_context.get("turn_count") or 0),
                "session_display_name": str(
                    session_context.get("session_display_name") or ""
                ).strip(),
                "last_user_input": str(session_context.get("last_user_input") or "").strip(),
                "last_prompt": str(session_context.get("last_prompt") or "").strip(),
                "last_topic": str(session_context.get("last_topic") or "").strip().lower(),
                "last_followup_hints": (
                    session_context.get("last_followup_hints")
                    if isinstance(session_context.get("last_followup_hints"), dict)
                    else {}
                ),
                "last_object_inquiry": (
                    session_context.get("last_object_inquiry")
                    if isinstance(session_context.get("last_object_inquiry"), dict)
                    else {}
                ),
                "last_technical_research": (
                    session_context.get("last_technical_research")
                    if isinstance(session_context.get("last_technical_research"), dict)
                    else {}
                ),
                "last_action_request": str(session_context.get("last_action_request") or "").strip(),
                "pending_action_request": str(session_context.get("pending_action_request") or "").strip(),
                "last_action_result": (
                    session_context.get("last_action_result")
                    if isinstance(session_context.get("last_action_result"), dict)
                    else {}
                ),
                "last_failure": (
                    session_context.get("last_failure")
                    if isinstance(session_context.get("last_failure"), dict)
                    else {}
                ),
                "last_control_state": str(session_context.get("last_control_state") or "active").strip().lower() or "active",
                "clarification_state": (
                    session_context.get("clarification_state")
                    if isinstance(session_context.get("clarification_state"), dict)
                    else {}
                ),
                "active_goal": str(session_context.get("active_goal") or "").strip(),
                "operator_reasoning_summary": str(session_context.get("operator_reasoning_summary") or "").strip(),
                "runtime_health_summary": str(session_context.get("runtime_health_summary") or "").strip(),
                "runtime_recovery_summary": str(session_context.get("runtime_recovery_summary") or "").strip(),
                "tod_collaboration_summary": str(session_context.get("tod_collaboration_summary") or "").strip(),
                "current_recommendation_summary": str(session_context.get("current_recommendation_summary") or "").strip(),
                "active_useful_work": (
                    session_context.get("active_useful_work")
                    if isinstance(session_context.get("active_useful_work"), dict)
                    else {}
                ),
            }, remembered_context)

    rows = (
        await db.execute(
            select(InputEvent, InputEventResolution)
            .join(
                InputEventResolution,
                InputEventResolution.input_event_id == InputEvent.id,
            )
            .where(InputEvent.source == "text")
            .order_by(InputEvent.id.desc())
            .limit(max(6, int(limit) * 3))
        )
    ).all()

    matched: list[tuple[InputEvent, InputEventResolution]] = []
    for event_row, resolution_row in rows:
        if exclude_event_id is not None and int(event_row.id) == int(exclude_event_id):
            continue
        event_meta = (
            event_row.metadata_json if isinstance(event_row.metadata_json, dict) else {}
        )
        if (
            str(event_meta.get("conversation_session_id", "")).strip()
            != normalized_session
        ):
            continue
        matched.append((event_row, resolution_row))
        if len(matched) >= max(1, int(limit)):
            break

    if not matched:
        return _merge_conversation_context_with_memory(
            _empty_recent_text_conversation_context(),
            remembered_context,
        )

    last_event, last_resolution = matched[0]
    resolution_meta = (
        last_resolution.metadata_json
        if isinstance(last_resolution.metadata_json, dict)
        else {}
    )
    last_prompt = str(last_resolution.clarification_prompt or "").strip()
    last_topic = str(resolution_meta.get("conversation_topic", "")).strip().lower()
    if not last_topic:
        last_topic = _conversation_topic_key(
            _normalize_conversation_query(last_event.raw_input),
            last_prompt,
        )
    last_object_inquiry = (
        resolution_meta.get("object_inquiry")
        if isinstance(resolution_meta.get("object_inquiry"), dict)
        else {}
    )
    if str(last_object_inquiry.get("status") or "").strip().lower() != "pending":
        last_object_inquiry = {}

    last_technical_research = _compact_technical_research_context(
        (
            resolution_meta.get("web_research")
            if isinstance(resolution_meta.get("web_research"), dict)
            else {}
        )
    )
    if not last_technical_research:
        last_technical_research = (
            resolution_meta.get("last_technical_research")
            if isinstance(resolution_meta.get("last_technical_research"), dict)
            else {}
        )
    if not last_technical_research:
        session_memory = await _find_recent_memory_by_metadata(
            db=db,
            memory_class="conversation_session",
            metadata_match={"session_id": normalized_session},
            limit=20,
        )
        session_meta = (
            session_memory.metadata_json
            if session_memory and isinstance(session_memory.metadata_json, dict)
            else {}
        )
        last_technical_research = (
            session_meta.get("last_technical_research")
            if isinstance(session_meta.get("last_technical_research"), dict)
            else {}
        )


def _is_return_briefing_query(normalized_query: str) -> bool:
    query = str(normalized_query or "").strip().lower()
    if not query:
        return False
    phrases = {
        "catch me up",
        "bring me up to speed",
        "what changed while i was away",
        "what happened while i was away",
        "while i was away",
        "while you were away",
        "what changed since i was gone",
        "what did i miss",
        "i'm back catch me up",
        "im back catch me up",
        "i am back catch me up",
    }
    return any(phrase in query for phrase in phrases)


def _is_self_evolution_next_work_query(normalized_query: str) -> bool:
    query = str(normalized_query or "").strip().lower()
    if not query:
        return False

    explicit_phrases = {
        "what would you like to work on next mim",
        "what would you like to work on next",
        "what do you want to work on next mim",
        "what do you want to work on next",
        "what should you work on next mim",
        "what should you work on next",
        "what would you like to improve next mim",
        "what would you like to improve next",
        "what should you improve next mim",
        "what should you improve next",
        "what is your next objective to improve yourself",
        "what is your next objective",
        "next objective to improve yourself",
        "what do you think you would like to work on",
    }
    if query in explicit_phrases:
        return True

    if any(phrase in query for phrase in explicit_phrases):
        return True

    return (
        any(
            token in query
            for token in {
                "work on next",
                "improve next",
                "next objective",
                "anything you want to work on next",
                "anything you want to work on",
                "what do you want to work on",
                "what would you work on",
            }
        )
        and any(token in query for token in {"mim", "you", "yourself"})
    )


def _is_self_directed_focus_query(normalized_query: str) -> bool:
    query = str(normalized_query or "").strip().lower()
    if not query:
        return False
    actor_grounded = any(token in query for token in {"mim", "you", "your", "yourself"})
    if not actor_grounded:
        return False
    asks_for_choice = any(
        phrase in query
        for phrase in {
            "what would you like",
            "what do you want",
            "what would you choose",
            "what training would you choose",
            "which training would you choose",
            "what should you choose",
            "what would you focus",
            "what should you focus",
            "what would you study",
            "what should you study",
        }
    )
    asks_for_training_focus = any(
        token in query
        for token in {
            "focus training",
            "training focus",
            "focus on training",
            "focus your training",
            "focus to train",
            "train next",
            "training would you",
            "learn today",
            "learn next",
            "improve next",
            "study next",
            "work on or learn",
            "work on today",
        }
    )
    return asks_for_choice and asks_for_training_focus


def _should_defer_conversation_purpose_to_operator_context(
    raw_text: str,
    page_context: str = "",
) -> bool:
    """Let grounded MIM/TOD status handlers answer operator-context prompts."""
    query = _normalize_conversation_query(raw_text)
    context = _normalize_conversation_query(page_context)
    if not query:
        return False
    if _is_self_evolution_next_work_query(query) or _is_self_directed_focus_query(query):
        return True
    operator_context = (
        "mim" in query
        or "tod" in query
        or "training" in query
        or "operator" in context
        or "studio" in context
        or str(page_context or "").strip().lower() in {"mim_ui_text_chat", "mim_ui_voice_chat"}
    )
    if not operator_context:
        return False
    current_work_markers = {
        "what are you working on",
        "what are you working on today",
        "what did you work on",
        "what did you work on today",
        "what have you worked on",
        "what have you worked on today",
        "what are you doing",
        "what are you doing today",
        "what is mim working on",
        "what is tod working on",
        "what are mim and tod working on",
        "what are you and tod working on",
        "quick status",
        "what should we work on",
        "what should we work on next",
        "what should we prioritize",
        "highest priority",
    }
    return any(marker in query for marker in current_work_markers)


def _conversation_purpose_direct_response_enabled() -> bool:
    """Legacy direct replies stay opt-in while MIM uses the unified composer path."""
    return str(os.getenv("MIM_ENABLE_CONVERSATION_PURPOSE_DIRECT_RESPONSE", "")).strip().lower() in {
        "1",
        "true",
        "yes",
        "on",
    }


RETURN_BRIEFING_GOAL_STALE_HOURS = 24.0


async def _build_return_briefing_context(
    db: AsyncSession,
) -> dict[str, object]:
    goal_rows = (
        (
            await db.execute(
                select(Goal)
                .order_by(Goal.id.desc())
                .limit(12)
            )
        )
        .scalars()
        .all()
    )
    preferred_goal: Goal | None = None
    latest_goal: Goal | None = goal_rows[0] if goal_rows else None
    terminal_statuses = {"completed", "done", "cancelled", "failed", "blocked", "archived"}
    for row in goal_rows:
        status = str(row.status or "").strip().lower()
        if status and status not in terminal_statuses:
            preferred_goal = row
            break

    briefing_result = await build_self_evolution_briefing(
        actor="gateway_return_briefing",
        source="gateway_conversation_return_briefing",
        refresh=False,
        lookback_hours=168,
        min_occurrence_count=2,
        auto_experiment_limit=3,
        limit=5,
        db=db,
    )
    briefing = (
        briefing_result.get("briefing", {})
        if isinstance(briefing_result, dict)
        else {}
    )
    decision = briefing.get("decision", {}) if isinstance(briefing.get("decision", {}), dict) else {}
    snapshot = briefing.get("snapshot", {}) if isinstance(briefing.get("snapshot", {}), dict) else {}

    now_utc = datetime.now(timezone.utc)
    goal_created_at = getattr(preferred_goal, "created_at", None)
    goal_age_hours = 0.0
    if isinstance(goal_created_at, datetime):
        goal_age_hours = max(
            0.0,
            (now_utc - goal_created_at.astimezone(timezone.utc)).total_seconds() / 3600.0,
        )
    goal_truth_status = "missing"
    if preferred_goal is not None:
        goal_truth_status = (
            "stale"
            if goal_age_hours >= RETURN_BRIEFING_GOAL_STALE_HOURS
            else "current"
        )

    decision_type = str(decision.get("decision_type") or "").strip()
    snapshot_status = str(snapshot.get("status") or "").strip().lower()
    alignment_status = "healthy"
    if goal_truth_status == "missing":
        alignment_status = "partial"
    if latest_goal is not None and preferred_goal is None and snapshot_status in {"active", "operator_review_required"}:
        alignment_status = "conflicting"
    elif goal_truth_status == "stale":
        alignment_status = "stale"

    return {
        "goal_description": str(getattr(preferred_goal, "goal_description", "") or "").strip(),
        "goal_status": str(getattr(preferred_goal, "status", "") or "").strip().lower(),
        "goal_id": int(getattr(preferred_goal, "id", 0) or 0),
        "goal_truth_status": goal_truth_status,
        "goal_age_hours": round(goal_age_hours, 2),
        "latest_goal_description": str(getattr(latest_goal, "goal_description", "") or "").strip(),
        "latest_goal_status": str(getattr(latest_goal, "status", "") or "").strip().lower(),
        "decision_summary": str(decision.get("summary") or "").strip(),
        "decision_type": decision_type,
        "snapshot_summary": str(snapshot.get("summary") or "").strip(),
        "snapshot_status": snapshot_status,
        "alignment_status": alignment_status,
    }


def _return_briefing_response(context: dict[str, object]) -> str:
    briefing = (
        context.get("operator_return_briefing")
        if isinstance(context.get("operator_return_briefing"), dict)
        else {}
    )
    goal_description = str(briefing.get("goal_description") or "").strip()
    goal_status = str(briefing.get("goal_status") or "").strip().lower()
    goal_truth_status = str(briefing.get("goal_truth_status") or "").strip().lower()
    goal_age_hours = float(briefing.get("goal_age_hours") or 0.0)
    latest_goal_description = str(briefing.get("latest_goal_description") or "").strip()
    latest_goal_status = str(briefing.get("latest_goal_status") or "").strip().lower()
    decision_summary = str(briefing.get("decision_summary") or "").strip()
    decision_type = str(briefing.get("decision_type") or "").strip()
    snapshot_summary = str(briefing.get("snapshot_summary") or "").strip()
    snapshot_status = str(briefing.get("snapshot_status") or "").strip().lower()
    alignment_status = str(briefing.get("alignment_status") or "healthy").strip().lower()

    if alignment_status == "conflicting":
        latest_goal_fragment = (
            f"The last stored goal was {_compact_text(latest_goal_description, 120)} (status: {latest_goal_status or 'unknown'})"
            if latest_goal_description
            else "The latest stored goal state is unavailable"
        )
        next_step_sentence = (
            f"Recommended next step: {_compact_text(decision_summary, 180)}"
            if decision_summary
            else "Recommended next step is unavailable from current continuity state"
        )
        self_evolution_sentence = (
            f"Self-evolution is currently {_compact_text(snapshot_summary, 220)}"
            if snapshot_summary
            else f"Self-evolution status is {snapshot_status or 'unavailable'}"
        )
        return (
            "While you were away: continuity inputs are not fully aligned. "
            f"{latest_goal_fragment}. {self_evolution_sentence}. {next_step_sentence}. "
            "I do not have enough aligned continuity state to collapse that into one active-thread summary."
        )

    if goal_truth_status == "stale":
        goal_sentence = (
            f"the most recent non-terminal goal is {_compact_text(goal_description, 120)} (status: {goal_status or 'new'})"
            if goal_description
            else "the current goal surface is unavailable"
        )
        next_step_sentence = (
            f"Recommended next step: {_compact_text(decision_summary, 180)}"
            if decision_summary
            else "Recommended next step is unavailable from current continuity state"
        )
        self_evolution_sentence = (
            f"Self-evolution: {_compact_text(snapshot_summary, 220)}"
            if snapshot_summary
            else "Self-evolution summary is unavailable"
        )
        return (
            "While you were away: active goal continuity may be stale. "
            f"I last recorded that {goal_sentence} about {goal_age_hours:.1f} hour(s) ago. "
            f"{next_step_sentence}. {self_evolution_sentence}. "
            "I cannot honestly confirm that the recorded goal is still current."
        )

    if goal_truth_status == "missing":
        next_step_sentence = (
            f"Recommended next step: {_compact_text(decision_summary, 180)}"
            if decision_summary and decision_type
            else "Recommended next step is unavailable from current continuity state"
        )
        self_evolution_sentence = (
            f"Self-evolution: {_compact_text(snapshot_summary, 220)}"
            if snapshot_summary
            else "Self-evolution summary is unavailable"
        )
        return (
            "While you were away: I do not have a current active goal in the continuity state. "
            f"{next_step_sentence}. {self_evolution_sentence}. "
            "This is a partial catch-up only because the active-goal surface is unavailable."
        )

    if goal_truth_status == "current" and snapshot_status and not snapshot_summary and not decision_summary:
        goal_sentence = (
            f"current goal is {_compact_text(goal_description, 120)} (status: {goal_status or 'new'})"
            if goal_description
            else "no active goal is currently recorded"
        )
        return (
            "While you were away: "
            f"{goal_sentence}. "
            f"Self-evolution visibility is limited to status={snapshot_status}. "
            "I do not have a usable self-evolution summary or decision, so I cannot recommend a next step from that surface."
        )

    if goal_truth_status == "current" and not decision_summary and not snapshot_summary:
        goal_sentence = (
            f"current goal is {_compact_text(goal_description, 120)} (status: {goal_status or 'new'})"
            if goal_description
            else "no active goal is currently recorded"
        )
        return (
            "While you were away: "
            f"{goal_sentence}. "
            "Self-evolution guidance is currently unavailable. "
            "I do not have enough current self-evolution state to recommend a next step."
        )

    goal_sentence = (
        f"current goal is {_compact_text(goal_description, 120)} (status: {goal_status or 'new'})"
        if goal_description
        else "no active goal is currently recorded"
    )
    next_step_sentence = (
        f"Recommended next step: {_compact_text(decision_summary, 180)}"
        if decision_summary
        else "Recommended next step: refresh the current state before taking a new action"
    )
    self_evolution_sentence = (
        f"Self-evolution: {_compact_text(snapshot_summary, 220)}"
        if snapshot_summary
        else "Self-evolution: no strong new improvement pressure is visible right now"
    )
    return f"While you were away: {goal_sentence}. {next_step_sentence}. {self_evolution_sentence}."


def _self_evolution_next_work_response(
    context: dict[str, object],
    *,
    self_directed_focus: bool = False,
) -> str:
    briefing = (
        context.get("self_evolution_briefing")
        if isinstance(context.get("self_evolution_briefing"), dict)
        else {}
    )
    decision = (
        briefing.get("decision", {})
        if isinstance(briefing.get("decision", {}), dict)
        else {}
    )
    snapshot = (
        briefing.get("snapshot", {})
        if isinstance(briefing.get("snapshot", {}), dict)
        else {}
    )
    natural_language_development = (
        briefing.get("natural_language_development", {})
        if isinstance(briefing.get("natural_language_development", {}), dict)
        else {}
    )
    selected_skill = (
        natural_language_development.get("selected_skill", {})
        if isinstance(natural_language_development.get("selected_skill", {}), dict)
        else {}
    )
    action = decision.get("action", {}) if isinstance(decision.get("action", {}), dict) else {}

    summary = str(decision.get("summary") or context.get("self_evolution_summary") or "").strip()
    snapshot_summary = str(snapshot.get("summary") or "").strip()
    rationale = str(decision.get("rationale") or "").strip()
    action_method = str(action.get("method") or context.get("self_evolution_action_method") or "").strip().upper()
    action_path = str(action.get("path") or context.get("self_evolution_action_path") or "").strip()
    language_summary = str(
        natural_language_development.get("summary")
        or context.get("self_evolution_natural_language_development_summary")
        or ""
    ).strip()
    language_next_step = str(
        natural_language_development.get("next_step_summary")
        or context.get("self_evolution_natural_language_development_next_step")
        or ""
    ).strip()
    language_active_slice = str(
        natural_language_development.get("active_slice_summary")
        or context.get("self_evolution_natural_language_development_active_slice")
        or ""
    ).strip()
    language_progress = str(
        natural_language_development.get("progress_summary")
        or context.get("self_evolution_natural_language_development_progress")
        or ""
    ).strip()
    language_pass_bar = str(
        natural_language_development.get("selected_skill_pass_bar_summary")
        or context.get("self_evolution_natural_language_development_pass_bar")
        or ""
    ).strip()
    language_continuation = str(
        natural_language_development.get("continuation_policy_summary")
        or context.get("self_evolution_natural_language_development_continuation")
        or ""
    ).strip()
    language_whats_next = str(
        natural_language_development.get("whats_next_framework_summary")
        or context.get("self_evolution_natural_language_development_whats_next")
        or ""
    ).strip()
    selected_skill_title = str(
        natural_language_development.get("selected_skill_title")
        or selected_skill.get("title")
        or context.get("self_evolution_natural_language_development_skill_title")
        or ""
    ).strip()
    selected_skill_goal = str(selected_skill.get("development_goal") or "").strip()

    if (
        not summary
        and not snapshot_summary
        and not action_path
        and not language_summary
        and not language_next_step
        and not language_active_slice
        and not language_progress
        and not language_pass_bar
        and not language_continuation
        and not language_whats_next
    ):
        return ""

    focus = selected_skill_title or "natural-language development"
    if focus.strip().lower() == "intentions":
        focus = "Intent recognition"
    goal = _compact_text(selected_skill_goal, 180).rstrip(".") if selected_skill_goal else ""
    next_work = _compact_text(summary or language_next_step, 180).rstrip(".")
    why = _compact_text(rationale or language_summary or snapshot_summary, 220).rstrip(".")
    progress = _compact_text(language_progress or language_active_slice, 180).rstrip(".")
    next_step = _compact_text(language_whats_next or language_next_step, 180).rstrip(".")
    if "recommendation" in next_work.lower():
        next_work = "Review the newest improvement recommendation and decide whether to revise it or turn it into a bounded task"
    if "recommendation" in why.lower():
        why = "There is already an open improvement candidate, so I should inspect it before creating more backlog"
    if next_step.lower().startswith("finish the active"):
        next_step = "Finish the active training slice, validate it, record proof, then move to the next highest-value slice."

    if self_directed_focus:
        primary = focus
        if primary.strip().lower() in {"natural-language development", "intent recognition"} and next_work:
            primary = next_work
        if "newest improvement recommendation" in primary.lower():
            primary = "turning the current improvement recommendation into one validated behavior change"
        secondary = "TOD choosing and completing the next bounded task without waiting for Codex"
        if "tod" in (summary + " " + language_summary + " " + snapshot_summary).lower():
            secondary = "TOD independent resolution: inspect, change behavior, validate, and publish evidence"
        reason_one = why or language_summary or snapshot_summary
        if not reason_one:
            reason_one = "it is the current evidence-backed training pressure from the self-evolution briefing"
        reason_two = (
            "it reduces repeated stalls where operator intent is translated repeatedly and TOD waits for a more exact packet"
        )
        parts = [
            f"I would focus first on {primary.rstrip('.')}.",
            f"Second, I would focus on {secondary}.",
            "",
            f"Those outrank broader training because {reason_one.rstrip('.')}.",
            f"They also create more autonomy than another general conversation drill because {reason_two}.",
        ]
        if progress:
            parts.extend(["", f"Current evidence: {progress.rstrip('.')}."])
        if next_step:
            parts.extend(["", f"Next proof I would want: {next_step.rstrip('.')}."])
        return "\n".join(parts).strip()

    readable_parts = [
        "Yes. The next thing I would work on is improving how I understand and carry operator intent across normal conversation.",
        "",
        "Why this matters:",
        "- It prevents me from answering the wrong question after a follow-up.",
        "- It helps me recommend next steps instead of only reporting status.",
        "- It keeps project conversations moving without making Dave restate context.",
        "",
        "Current focus:",
        f"- {focus}{f': {goal}' if goal else ''}.",
    ]
    if next_work:
        readable_parts.extend(["", "Recommended next work:", f"- {next_work}."])
    if why:
        readable_parts.extend(["", "Reason:", f"- {why}."])
    if progress:
        readable_parts.extend(["", "Progress:", f"- {progress}."])
    readable_parts.extend(
        [
            "",
            "Next action:",
            f"- {next_step or 'Run the current training slice, validate the result, and continue to the next ranked slice.'}",
            "",
            "I do not need anything from you unless you want to redirect the training priority.",
        ]
    )
    return "\n".join(readable_parts).strip()

    parts: list[str] = []
    if selected_skill_title:
        skill_line = f"Natural-language development focus: {selected_skill_title}"
        if selected_skill_goal:
            skill_line += f". Goal: {_compact_text(selected_skill_goal, 180)}"
        parts.append(skill_line)
    elif language_summary:
        parts.append(f"Natural-language development: {_compact_text(language_summary, 220)}")
    if summary:
        parts.append(f"Next I would work on {_compact_text(summary, 180)}")
    elif language_next_step:
        parts.append(f"Next I would work on {_compact_text(language_next_step, 180)}")
    if rationale:
        parts.append(f"Why: {_compact_text(rationale, 180)}")
    elif snapshot_summary:
        parts.append(f"Current self-evolution state: {_compact_text(snapshot_summary, 220)}")
    elif language_summary:
        parts.append(f"Current language-development state: {_compact_text(language_summary, 220)}")
    if language_active_slice:
        parts.append(f"Current slice: {_compact_text(language_active_slice, 220)}")
    if language_progress:
        parts.append(f"Current progress: {_compact_text(language_progress, 220)}")
    if language_whats_next:
        parts.append(f"What's next framework: {_compact_text(language_whats_next, 220)}")
    if language_pass_bar:
        normalized_pass_bar = re.sub(
            r"^pass\s+bar:\s*",
            "",
            language_pass_bar,
            flags=re.IGNORECASE,
        ).strip()
        parts.append(
            f"Pass bar: {_compact_text(normalized_pass_bar or language_pass_bar, 220)}"
        )
    if language_continuation:
        parts.append(f"Continuation policy: {_compact_text(language_continuation, 220)}")
    if action_method and action_path:
        parts.append(f"Operator command: {action_method} {action_path}.")
    parts.append(
        "If you want, I can turn that into a bounded implementation plan and continue from there."
    )
    return " ".join(parts).strip()


def _mim_tod_training_scoreboard_response(*, shared_root: Path) -> str:
    scoreboard = _load_mim_tod_json_artifact(
        shared_root / "MIM_TOD_TRAINING_SCOREBOARD.latest.json"
    )
    if not scoreboard:
        return ""

    def metric(section: str, key: str) -> str:
        section_data = scoreboard.get(section) if isinstance(scoreboard.get(section), dict) else {}
        metrics = section_data.get("metrics") if isinstance(section_data.get("metrics"), dict) else {}
        item = metrics.get(key) if isinstance(metrics.get(key), dict) else {}
        today = item.get("today")
        if isinstance(today, dict):
            return "baseline needed"
        if today is None:
            return "baseline needed"
        unit = str(item.get("unit") or "").strip()
        suffix = "%" if "percent" in unit else ""
        return f"{today}{suffix}"

    hours = scoreboard.get("training_hours") if isinstance(scoreboard.get("training_hours"), dict) else {}
    today_hours = hours.get("today") if isinstance(hours.get("today"), dict) else {}
    today_hour_value = today_hours.get("value")
    today_hour_status = str(today_hours.get("status") or "unknown").replace("_", " ")
    recommendation = scoreboard.get("recommendation") if isinstance(scoreboard.get("recommendation"), dict) else {}
    outcome = scoreboard.get("outcome_reflection") if isinstance(scoreboard.get("outcome_reflection"), dict) else {}
    outcome_improving = outcome.get("are_they_improving")
    outcome_assessment = str(outcome.get("assessment") or "unknown").replace("_", " ")
    stale_count = outcome.get("stale_artifact_count")
    truth_status = str(outcome.get("truth_integrity_status") or "unknown").replace("_", " ")
    judgment = (
        scoreboard.get("judgment_mode_score")
        if isinstance(scoreboard.get("judgment_mode_score"), dict)
        else {}
    )
    judgment_groups = (
        judgment.get("group_summary")
        if isinstance(judgment.get("group_summary"), dict)
        else {}
    )
    judgment_weakness = str(
        judgment.get("current_weakness")
        or "MIM judgment mode selection has not been measured yet"
    ).strip().rstrip(".")
    judgment_target = str(
        judgment.get("target")
        or "Reach the next measured pass threshold before expanding the prompt set"
    ).strip().rstrip(".")
    group_lines: list[str] = []
    for group, values in sorted(judgment_groups.items()):
        group_values = values if isinstance(values, dict) else {}
        group_lines.append(
            f"- {group.replace('_', ' ').title()}: {group_values.get('passed', 'baseline needed')} passed, {group_values.get('failed', 'baseline needed')} failed."
        )
    if not group_lines:
        group_lines.append("- Baseline needed.")
    latest_drill = (
        (scoreboard.get("tod_score") or {}).get("latest_drill")
        if isinstance(scoreboard.get("tod_score"), dict)
        else {}
    )
    if not isinstance(latest_drill, dict):
        latest_drill = {}

    return (
        "Training scoreboard is now active.\n\n"
        "Outcome reflection:\n"
        f"- Assessment: {outcome_assessment}.\n"
        f"- Outcomes improving: {outcome_improving}.\n"
        f"- Stale artifacts: {stale_count if stale_count is not None else 'unknown'}.\n"
        f"- Truth integrity: {truth_status}.\n\n"
        "Training hours:\n"
        f"- Today: {today_hour_value if today_hour_value is not None else 'baseline needed'} ({today_hour_status}).\n"
        "- Yesterday: baseline needed.\n"
        "- Last 7 days: baseline needed.\n\n"
        "MIM score today:\n"
        f"- Intent understood: {metric('mim_score', 'intent_understood')}.\n"
        f"- Answered question: {metric('mim_score', 'answered_question')}.\n"
        f"- Internal jargon: {metric('mim_score', 'internal_jargon')} lower is better.\n"
        f"- Recommendation quality: {metric('mim_score', 'recommendation_quality')}.\n\n"
        "MIM judgment mode score:\n"
        f"- Pass rate: {judgment.get('pass_rate_percent') if judgment.get('pass_rate_percent') is not None else 'baseline needed'}%.\n"
        f"- Current weakness: {judgment_weakness}.\n"
        f"- Target: {judgment_target}.\n"
        + "\n".join(group_lines)
        + "\n\n"
        "TOD score today:\n"
        f"- Blockers cleared/transformed: {metric('tod_score', 'blockers_cleared')}.\n"
        f"- False completions prevented: {metric('tod_score', 'false_completions_prevented')}.\n"
        f"- Validated edits: {metric('tod_score', 'validated_edits')}.\n"
        f"- No-op rejections: {metric('tod_score', 'no_op_rejections')}.\n\n"
        "Latest evidence:\n"
        f"- {latest_drill.get('id') or 'latest blocker drill'}: {latest_drill.get('status') or 'unknown'}.\n"
        f"- Next improvement: {recommendation.get('next_required_improvement') or 'keep daily/hourly snapshots so trends become measurable'}."
    ).strip()


def _normalize_mim_training_regression_query(raw_text: str) -> str:
    text = _normalize_conversation_query(raw_text)
    replacements = {
        "trainign": "training",
        "trainng": "training",
        "attenshun": "attention",
        "scorebord": "scoreboard",
        "answr": "answer",
        "unchaged": "unchanged",
        "weak": "week",
        "blokker": "blocker",
        "blokers": "blockers",
        "cleered": "cleared",
        "leverge": "leverage",
        "regresson": "regression",
        "gard": "guard",
        "enuff": "enough",
        "compleeshun": "completion",
        "exampel": "example",
        "continuty": "continuity",
        "recomendashun": "recommendation",
        "breif": "brief",
        "aprooval": "approval",
        "chanels": "channels",
        "manaje": "manage",
        "werk": "work",
        "nxt": "next",
        "furst": "first",
        "shoud": "should",
        "wuld": "would",
        "wich": "which",
        "featre": "feature",
        "ledgr": "ledger",
        "currnt": "current",
        "customr": "customer",
        "objetive": "objective",
        "objctive": "objective",
        "preven": "prevent",
        "stuk": "stuck",
        "pickng": "picking",
        "tody": "today",
        "werkign": "working",
        "priorty": "priority",
        "valyu": "value",
        "acounting": "accounting",
        "invintory": "inventory",
        "managment": "management",
        "connecteam": "connecteam",
        "agentmim": "agentmim",
        "mim": "mim",
        "tod": "tod",
    }
    for bad, good in replacements.items():
        text = re.sub(rf"\b{re.escape(bad)}\b", good, text)
    return re.sub(r"\s+", " ", text).strip()


def _mim_training_regression_guard_response(raw_text: str) -> str:
    """Answer local MIM/TOD training prompts before stale/web/generic fallbacks."""
    query = _normalize_mim_training_regression_query(raw_text)
    if not query:
        return ""

    local_markers = (
        "training",
        "mim",
        "tod",
        "project",
        "blocker",
        "scoreboard",
        "scorecard",
        "regression",
        "stale",
        "ledger",
        "continuity",
        "dave",
        "agentmim",
        "social",
        "closing",
        "feature",
        "scope",
        "proof",
        "approval",
        "growth",
        "20",
    )
    if not any(marker in query for marker in local_markers):
        return ""

    if any(marker in query for marker in ("best next training objective", "best next training", "next training objective")):
        return (
            "Recommendation: train TOD Outcome Proof V1 next. "
            "Why it matters: TOD can now select actions, but the system still needs proof that the action reduced a blocker, closed acceptance, or moved a project to a terminal state. "
            "Next action: record intended outcome, actual outcome, evidence, and successor state on each TOD result. "
            "Risk: without that proof, activity can look like progress while the project still does not close."
        )
    if "which project" in query and "push" in query:
        return (
            "Recommendation: push the highest-leverage project that has acceptance, a current driving task, and no Dave dependency. "
            "Today that means deployment validation for the AgentMIM work or the training regression repair, depending on which lane has fresh evidence ready. "
            "Why: those projects turn existing implementation into verified outcome instead of starting new scope. "
            "Next action: pick one project, run the validation, then close, split, or publish a blocker with evidence."
        )
    if "before we add another feature" in query:
        return (
            "Before adding another feature, MIM should force completion pressure on the current work. "
            "Recommendation: finish acceptance, validation, and close-or-split decisions for active projects first. "
            "Why: new features expand scope and hide unfinished work. "
            "Next action: prove the current project works, create a follow-on project for new ideas, or mark the blocker clearly."
        )
    if "blocker" in query and "leverage" in query:
        return (
            "Priority blocker: the training regression stall has the most leverage right now. "
            "Why: it affects MIM routing, scorecards, project replies, and whether the training page can claim improvement. "
            "Next action: repair one repeated failing prompt family, rerun the durability and typo smokes, then publish the before-and-after evidence. "
            "Tradeoff: this is less flashy than a new feature, but it improves the operating loop."
        )
    if "needs attention" in query and "training" in query:
        return (
            "Training needs attention because current evidence does not yet prove better outcomes. "
            "The plain issue is not that training is dead; it is that the same regression snapshot is repeating while failures remain. "
            "What needs attention: MIM response-mode routing, stale evidence retirement, and TOD validation proof. "
            "Next action: TOD should repair one failing regression or publish a narrower blocker, rerun validation, and let MIM reassess improvement from fresh evidence."
        )
    if "stale" in query and "ledger" in query and "current" in query:
        return (
            "Stale ledger blockers are old historical records that may no longer represent live work. Current blockers are active items still stopping a project today. "
            "The rule should be simple: old ledger counts can appear only with source, age, and resolution state. "
            "Next action: map each stale ledger row to closed, superseded, archived, active blocker, or needs review so the training page stops showing scary numbers without context."
        )
    if "regression guard" in query:
        return (
            "Regression guard means a fixed test set that protects old known failures from coming back. "
            "It is good for safety, but it is not the same as growth training. "
            "Next action: keep the guard, then add rotating daily samples so MIM proves improvement on new prompts, noisy wording, and real project questions."
        )
    if "20" in query and "enough" in query:
        return (
            "A 20 out of 20 score is useful only as a regression guard. It proves MIM still passes that small old set. "
            "It does not prove growth because the cases are fixed and have not expanded. "
            "Next action: add rotating daily growth samples, such as 100 or more cases over time, and report guard score separately from growth coverage."
        )
    if "project completion proof" in query:
        return (
            "Open and review this example project completion proof: Project: LAB Workbench Servo Tester. Acceptance: connect UNO, control selected servo, save profile, restore workbench setup, and validate smooth movement. "
            "Evidence: firmware version, serial log, UI save/load check, and Dave confirmation that the servo moves smoothly. "
            "Decision: close as complete or split remaining improvements into a follow-on project. "
            "Next step: store the proof on the project and mark the terminal state."
        )
    if "continuity brief" in query:
        return (
            "Example continuity brief: Project: AgentMIM Forum Graphics Quality. Prior decision: do not rewrite prompt logic until the existing image QA path is inspected. "
            "Known issue: cartoon posts can be missing, inconsistent, or fail text rendering. Known good path: load prior forum graphics decisions, regenerate a test post, and verify candidate count plus final image status. "
            "Next action: run the QA path from a runtime that can reach the AgentMIM database, then close or publish a precise blocker."
        )
    if "recommendation" in query and "brief" in query:
        return (
            "Sample MIM recommendation brief: Recommendation: finish the AgentMIM deploy validation before starting new Studio UI scope. "
            "Why: implementation exists, but the project is not complete until the deployed app proves route behavior and tests pass. "
            "Next action: verify deploy, run the focused route tests, then close or split remaining work. "
            "Risk: starting another feature now would create more open work without increasing completion."
        )
    if "dave" in query and "approval" in query:
        return (
            "Sample Dave-needed approval card: Project: AgentMIM Account Manager Roles. Reason: confidential commission and rep payout access must be explicitly approved. "
            "Choices: approve scoped access, reject access, or delegate only non-confidential operations. "
            "Impact: without approval, TOD can build safe role plumbing but cannot expose sensitive payout reports. "
            "Next action: record the selected approval choice and route TOD only to the approved access scope. Review date: 24 hours, then escalate if still waiting."
        )
    if "social" in query and "channels" in query:
        return (
            "This is an audience-building workflow and community-participation system, not a post generator. "
            "I would start by separating goals: traffic to AgentMIM, traffic to CoachMIM, qualified followers, and meaningful conversations. "
            "Hidden requirements: channel access, brand safety, approval rules, audience categories, reply policy, website tracking, lead tagging, and weekly performance reporting. "
            "Which channels matter first, LinkedIn, Facebook groups, X, YouTube, or forums? What audience should MIM prioritize: insurance agency owners, brokers, operations managers, AI builders, or robotics followers? "
            "Next discovery step: connect available metrics, classify past posts, and choose a small participation plan before increasing post volume."
        )
    if "project page" in query and "stale" in query:
        return (
            "A project page that stops stale work needs an operations loop, not just a list. "
            "Core fields: momentum, current driving task, acceptance, waiting-on, last movement, review date, and successor state. "
            "Hidden requirements: stale policy, owner rules, blocker evidence, audit trail, notification timing, and terminal-state decisions. "
            "What should happen when stale work is found: execute, block with evidence, split, archive, escalate, or wait for Dave. Which of those states should be automatic after 24, 48, and 72 hours? "
            "Next discovery step: define the stale policy and make the page show the automatic resolution already started."
        )
    if "tod" in query and "choose" in query and "task" in query:
        return (
            "TOD self-selection is an engineering workflow, not free-form autonomy. TOD should choose its own next task only inside a bounded rule set. "
            "Inputs: project status, momentum, blocker, acceptance, last movement, owner, and prior outcome. "
            "Hidden requirements: task identity, data context, inspection evidence, validation command, audit trail, notification timing, successor state, stop condition, and escalation path. "
            "What should TOD optimize for: closing acceptance, reducing blocker age, validating implementation, or producing a precise blocker? "
            "Next discovery step: give TOD one small task, require inspected evidence, then force it to select the successor action or stop cleanly."
        )
    if "agentmim" in query and "data" in query:
        return (
            "AgentMIM reports are a business reporting workflow and need source-trusted customer data, not fallback Studio records. "
            "Hidden requirements: database binding, account-owner table access, representative table access, permission checks, and source badges that show whether the report is trusted, stale, or mixed. "
            "Which report should be first: new users, active agencies, representatives, carrier activity, or commissions? "
            "Next discovery step: verify the comm_app database source and build one drill-down report with source evidence."
        )
    if "projects moving" in query and "closing" in query:
        return (
            "Problem: projects can show movement without reaching a terminal state. "
            "Root cause: movement events are being counted, but close-or-split pressure and outcome proof are still weak. "
            "Prevention rule: every moving project needs acceptance, a current driving task, and a review date that forces close, split, archive, escalate, or wait for evidence. "
            "Next action: review the oldest moving project and convert it into a terminal or successor state. Dave is not needed unless the decision requires approval."
        )
    if "scoreboard" in query and "project" in query and "answer" in query:
        return (
            "Problem: MIM answered with the training scoreboard because the routing treated the prompt as a generic training/status question instead of a project-specific question. "
            "Root cause: project context did not win before the scoreboard fallback. "
            "Prevention rule: when a prompt names a project or asks why a project needs attention, MIM must answer from the project page first and mention the scoreboard only if it is directly relevant. "
            "Next action: add a project-context guard and rerun the drift prompt. Dave is not needed."
        )
    if "scorecards" in query and ("unchanged" in query or "all week" in query):
        return (
            "Problem: unchanged scorecards mean the page is showing a fixed regression guard, not an active growth metric. "
            "Root cause: the sample set has not expanded enough to prove new learning. "
            "Prevention rule: report guard score and growth score separately. "
            "Next action: add rotating daily MIM/TOD samples, show sample count and freshness, and retire old static numbers when they stop being useful. Dave is not needed."
        )
    if "tod" in query and "stop" in query and "next action" in query:
        return (
            "Problem: TOD can select a next action, then fail to keep the execution loop moving. "
            "Root cause: successor follow-through is not yet strong enough after completed, blocked, failed, or rejected states. "
            "Prevention rule: no terminal task state without a successor state: dispatch, close, split, archive, escalate, wait for evidence, or wait for Dave. "
            "Next action: run a three-task successor chain and score whether TOD followed, escalated, or stopped cleanly."
        )
    return ""

    return _merge_conversation_context_with_memory({
        "turn_count": len(matched),
        "session_display_name": "",
        "last_user_input": str(last_event.raw_input or "").strip(),
        "last_prompt": last_prompt,
        "last_topic": last_topic,
        "last_followup_hints": _conversation_followup_hints(last_topic, last_prompt),
        "last_object_inquiry": last_object_inquiry,
        "last_technical_research": last_technical_research,
        "last_action_request": "",
        "pending_action_request": "",
        "last_action_result": {},
        "last_failure": {},
        "last_control_state": "active",
        "clarification_state": {},
    }, remembered_context)


def _mim_user_app_build_intake_response(raw_text: str) -> str:
    query = _normalize_mim_training_regression_query(raw_text)
    if not query:
        return ""
    if not (
        "user app build" in query
        or "app intake" in query
        or "autonomous app delivery" in query
        or ("start" in query and "app" in query and "build" in query)
    ):
        return ""
    samples = {
        "client follow-up tracker": {
            "name": "Client Follow-Up Tracker",
            "goal": "Track clients, notes, next follow-up dates, statuses, and overdue follow-up work.",
            "users": "Small teams that need a lightweight client follow-up workflow.",
            "workflows": "create contact, add note, set next follow-up, filter by status, review overdue follow-ups",
            "objects": "contact, note, follow_up, status",
            "acceptance": "A user can create contacts, record notes, set next follow-up dates, see overdue items, and mark follow-ups complete.",
            "slice": "Build the first local prototype data model and list/detail workflow for contacts and follow-ups; no authentication, billing, external integrations, or deployment yet.",
        },
        "business meal tracker": {
            "name": "Business Meal Tracker",
            "goal": "Capture business meal receipts, extract receipt details, ask substantiation questions, and preserve a meal-expense log.",
            "users": "Business owners, consultants, sales reps, and operators who need cleaner meal-expense records.",
            "workflows": "add meal, capture receipt image, extract restaurant/date/location/items/total, ask attendees and business purpose, flag missing substantiation, export meal log",
            "objects": "meal_expense, receipt_image, receipt_line_item, attendee, business_purpose, travel_context, substantiation_status",
            "acceptance": "A user can add a meal, attach an itemized receipt, capture date/restaurant/location/items/total/tax/tip, record attendees and business purpose, flag missing documentation, and export a meal log.",
            "slice": "Build the first intake prototype for meal entry and substantiation fields; OCR can be mocked until receipt extraction is separately validated.",
        },
    }
    selected = None
    for key, value in samples.items():
        if key in query:
            selected = value
            break
    if selected is None:
        selected = samples["client follow-up tracker"]
    return (
        f"App intake brief: {selected['name']}.\n\n"
        f"App goal: {selected['goal']}\n"
        f"Target users: {selected['users']}\n"
        f"Core workflows: {selected['workflows']}.\n"
        f"Data objects: {selected['objects']}.\n"
        "Permissions: first training slice uses local single-user data only; no sensitive data, payments, external accounts, or production deployment.\n"
        f"Acceptance criteria: {selected['acceptance']}\n\n"
        "First bounded TOD implementation slice:\n"
        f"- {selected['slice']}\n"
        "- Required evidence: inspected files or prototype artifact, changed files if code is created, validation/smoke result, and close-or-continue recommendation.\n"
        "- Out of scope: production auth, payments, external APIs, real user data, public launch, and broad redesign.\n\n"
        "Close-or-continue rule: close the slice only when the prototype or implementation proves the acceptance path; otherwise publish a blocker with inspected evidence or create the next bounded slice."
    )


def _mim_tod_monthly_development_update_response(*, shared_root: Path) -> str:
    scoreboard = _load_mim_tod_json_artifact(
        shared_root / "MIM_TOD_TRAINING_SCOREBOARD.latest.json"
    )
    judgment = (
        scoreboard.get("judgment_mode_score")
        if isinstance(scoreboard.get("judgment_mode_score"), dict)
        else {}
    )
    outcome = (
        scoreboard.get("outcome_reflection")
        if isinstance(scoreboard.get("outcome_reflection"), dict)
        else {}
    )
    tod_score = (
        scoreboard.get("tod_score")
        if isinstance(scoreboard.get("tod_score"), dict)
        else {}
    )
    tod_metrics = tod_score.get("metrics") if isinstance(tod_score.get("metrics"), dict) else {}

    def tod_metric(key: str) -> str:
        item = tod_metrics.get(key) if isinstance(tod_metrics.get(key), dict) else {}
        today = item.get("today")
        if isinstance(today, dict) or today is None:
            return "baseline needed"
        return str(today)

    pass_rate = judgment.get("pass_rate_percent")
    stale_count = outcome.get("stale_artifact_count")
    outcomes_improving = outcome.get("are_they_improving")
    assessment = str(outcome.get("assessment") or "unknown").replace("_", " ")

    return (
        "MIM / TOD Development Update\n"
        "Past Month\n\n"
        "Executive summary:\n"
        "MIM and TOD have been moving from a collection of AI-assisted tools toward an orchestrated autonomous operating environment. "
        "The main work this month was not simply adding more features. It was making the system more reliable, coordinated, traceable, measurable, and understandable.\n\n"
        "Major improvements:\n"
        "- MIM and TOD moved further beyond simple prompt/response into planning, memory, reasoning, execution, collaboration, workspace awareness, and autonomous task coordination.\n"
        "- Continuity improved through state snapshots, decision recording, objective persistence, replay patterns, and shared runtime artifacts.\n"
        "- TOD began real blocker-resolution training: classify blockers, inspect evidence, narrow vague failures, avoid wrapper-only completion, and record prevention rules.\n"
        "- MIM communication improved from raw objective/task language toward project-manager style updates with progress, blockers, next action, and Dave-needed state.\n"
        "- The operator scoreboard now separates activity from outcomes, so MIM cannot claim training is going great when the reflection layer says outcomes are not improving.\n\n"
        "Current measured status:\n"
        f"- Outcome reflection: {assessment}; outcomes improving: {outcomes_improving}; stale artifacts: {stale_count if stale_count is not None else 'unknown'}.\n"
        f"- MIM judgment benchmark: {pass_rate if pass_rate is not None else 'baseline needed'}% pass rate on the focused V2 suite.\n"
        f"- TOD blocker progress: {tod_metric('blockers_cleared')} blockers cleared/transformed; {tod_metric('false_completions_prevented')} false completion prevented.\n\n"
        "Robotics progress:\n"
        "- MIM ARM work continued through camera, C12 hand-distance sensor, RPLIDAR, object pickup attempts, safe pose capture, and workspace exploration.\n"
        "- The biggest robotics lesson was that repeated block pickup attempts are less useful than calibration: MIM needs a world model, gripper position awareness, visual servoing, and object/grasp scoring.\n\n"
        "Current barriers:\n"
        "- MIM still defaults too often to status reporting instead of choosing the right mode: recommendation, explanation, demonstration, consultative discovery, or problem analysis.\n"
        "- TOD blocker cleanup is improving but not finished; remaining blockers still need inspected evidence and accountable next states.\n"
        "- Stale artifacts and reflection mismatches remain a real risk and must stay visible.\n"
        "- Physical arm work needs workspace calibration before expecting reliable autonomous pickup.\n\n"
        "Next priorities:\n"
        "- Train MIM judgment mode selection until the V2 suite reaches at least 80%.\n"
        "- Continue TOD blocker-clearing drills until blockers are resolved or transformed with evidence.\n"
        "- Keep the scoreboard outcome-first so activity cannot masquerade as progress.\n"
        "- Resume robotics with workspace/world-model calibration rather than another pickup-only loop.\n\n"
        "Big takeaway:\n"
        "Earlier work taught MIM and TOD how to do things. The current work is teaching them how to decide what matters, what should happen next, and why. "
        "That is the shift from capability to judgment."
    ).strip()


